"use client";

import Link from "next/link";
import { Children, cloneElement, isValidElement, useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import { toast } from "sonner";
import { Activity as ActivityIcon, AlertTriangle, ArrowDownToLine, ArrowDownRight, ArrowRight, ArrowUpRight, Boxes, CalendarDays, Check, ChevronRight, CircleAlert, CircleCheck, CircleDot, ClipboardList, Factory, FileUp, PackageCheck, PackagePlus, Plus, RefreshCw, RotateCcw, Scale, Search, ShieldAlert, Trash2, Truck, UserRound } from "lucide-react";
import { useForge } from "@/components/providers/forge-provider";
import { PageHeader } from "@/components/layout/page-header";
import { KpiTile } from "@/components/shared/kpi-tile";
import { StatusBadge } from "@/components/shared/status-badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Sheet, SheetContent, SheetDescription, SheetTitle } from "@/components/ui/sheet";
import { formatDate, formatNumber, isForgeData, makeId, toDateInputValue, type ForgeData, type OrderStatus, type ProductionOrder, type Vendor } from "@/lib/domain";
import { calculateOrderFlow, calculateReconciliationProgress, nextVendorCode, normalizeExternalId, previewVendorUpdateImport, recordDispatch, recordInspection, recordInvoice, recordReceipt, recordShipment, serializeCsvRow } from "@/lib/workflow";

type Section = "dashboard" | "orders" | "order" | "vendors" | "vendor" | "receipts" | "quality" | "reconciliation" | "imports" | "history";
type DashboardRange = "Today" | "7d" | "30d" | "90d" | "QTD";
const titles: Record<Section, [string, string]> = {
  dashboard: ["Dashboard", ""],
  orders: ["Production orders", "Plan, track, and update work orders from release through shipment."],
  order: ["Production order", "Review order progress, receipts, inspection, and reconciliation."],
  vendors: ["Vendors", "Manage the suppliers and subcontractors supporting production."],
  vendor: ["Vendor profile", "Review a supplier's contact details and active workload."],
  receipts: ["Warehouse receipts", "Record goods received against production orders."],
  quality: ["Quality inspection", "Inspect received quantities and record accepted or rejected units."],
  reconciliation: ["Vendor reconciliation", "Compare vendor reported, received, and accepted quantities."],
  imports: ["Vendor update import", "Load vendor progress updates from CSV, detect duplicates, and retry failures."],
  history: ["Activity history", "Review changes made in this browser and export or reset demo data."],
};

const statuses: OrderStatus[] = ["Pending", "In Progress", "Blocked", "Completed", "Shipped"];
const inputClass = "min-w-0";
const fieldClass = "grid gap-1.5 text-xs font-medium text-muted-foreground";
const selectClass = "h-9 w-full rounded-md border border-input bg-background px-3 text-sm text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring";
const panelClass = "rounded-xl border bg-card p-5 shadow-sm";

function Field({ label, children }: { label: string; children: ReactNode }) { return <label className={fieldClass}>{label}{children}</label>; }
function TextField({ label, name, type = "text", required = true, defaultValue, placeholder }: { label: string; name: string; type?: string; required?: boolean; defaultValue?: string; placeholder?: string }) {
  return <Field label={label}><Input className={inputClass} name={name} type={type} required={required} defaultValue={defaultValue} placeholder={placeholder} min={type === "number" ? 0 : undefined} step={type === "number" ? 1 : undefined} /></Field>;
}
function DataTable({ children }: { children: ReactNode }) { return <div className="w-full overflow-x-auto"><table className="w-full min-w-full text-sm">{children}</table></div>; }
function Row({ children, head = false }: { children: ReactNode; head?: boolean }) { return <tr className={head ? "border-b text-left text-xs text-muted-foreground" : "border-b last:border-0 hover:bg-muted/30"}>{children}</tr>; }
function Cell({ children, head = false, className = "", title }: { children: ReactNode; head?: boolean; className?: string; title?: string }) { const Tag = head ? "th" : "td"; return <Tag title={title} className={`whitespace-nowrap px-3 py-3 ${head ? "font-medium" : ""} ${className}`}>{children}</Tag>; }
function TableHead({ children }: { children: ReactNode }) { return <thead><Row head>{children}</Row></thead>; }
function TableWrap({ headers, children, serialOffset = 0 }: { headers: string[]; children: ReactNode; serialOffset?: number }) { const rows = Children.map(children, (child, index) => isValidElement<{ children?: ReactNode }>(child) ? cloneElement(child, { children: <><Cell className="w-14 text-xs tabular-nums text-muted-foreground">{serialOffset + index + 1}</Cell>{child.props.children}</> }) : child); return <div className={`${panelClass} overflow-hidden p-0`}><DataTable><TableHead><Cell head className="w-14">S.No.</Cell>{headers.map((h) => <Cell head key={h}>{h}</Cell>)}</TableHead><tbody>{rows}</tbody></DataTable></div>; }
function Empty({ children }: { children: ReactNode }) { return <div className="p-8 text-center text-sm text-muted-foreground">{children}</div>; }

function OrderCreationDrawer({ open, onOpenChange, vendors, onCreate }: { open: boolean; onOpenChange: (open: boolean) => void; vendors: Vendor[]; onCreate: (values: FormData) => boolean }) {
  const activeVendors = vendors.filter((vendor) => vendor.status === "Active");
  const [product, setProduct] = useState("");
  const [quantity, setQuantity] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [vendorId, setVendorId] = useState(activeVendors[0]?.id ?? "");
  const [customerName, setCustomerName] = useState("");
  const [customerOrderCode, setCustomerOrderCode] = useState("");
  const [shipmentDueDate, setShipmentDueDate] = useState("");
  const selectedVendor = activeVendors.find((vendor) => vendor.id === vendorId);
  const parsedQuantity = Number(quantity);
  const quantityValid = Number.isSafeInteger(parsedQuantity) && parsedQuantity > 0;
  const resetDraft = () => { setProduct(""); setQuantity(""); setDueDate(""); setVendorId(activeVendors[0]?.id ?? ""); setCustomerName(""); setCustomerOrderCode(""); setShipmentDueDate(""); };
  const handleOpenChange = (next: boolean) => { onOpenChange(next); if (!next) resetDraft(); };
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (onCreate(new FormData(event.currentTarget))) resetDraft();
  };
  const canSubmit = product.trim().length > 0 && quantityValid && !!dueDate && !!selectedVendor;

  return <Sheet open={open} onOpenChange={handleOpenChange}>
    <SheetContent aria-describedby="new-order-description" className="flex h-dvh w-full max-w-none flex-col gap-0 overflow-hidden p-0 sm:max-w-xl">
      <div className="border-b bg-gradient-to-br from-primary/[0.08] via-background to-background px-5 py-5 pr-14 sm:px-7 sm:py-6">
        <div className="flex items-start gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><PackagePlus aria-hidden="true" className="size-5" /></span><div className="min-w-0"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Production planning</p><SheetTitle className="mt-1 text-xl font-semibold tracking-tight">Create production order</SheetTitle><SheetDescription id="new-order-description" className="sr-only">Create a production order.</SheetDescription></div></div>
      </div>

      <form onSubmit={handleSubmit} className="flex min-h-0 flex-1 flex-col">
        <div className="min-h-0 flex-1 space-y-6 overflow-y-auto px-5 py-5 sm:px-7 sm:py-6">
          <section aria-labelledby="order-details-heading" className="space-y-3.5">
            <div className="flex items-start justify-between gap-3"><div><h3 id="order-details-heading" className="text-sm font-semibold">Production details</h3><p className="mt-0.5 text-[11px] text-muted-foreground">The product and quantity on the production plan.</p></div><span className="rounded-full border bg-muted/40 px-2 py-1 text-[9px] font-medium text-muted-foreground">Required</span></div>
            <label htmlFor="new-order-product" className={fieldClass}>Product / process<Input autoFocus id="new-order-product" name="product" required value={product} onChange={(event) => setProduct(event.target.value)} placeholder="e.g. Drive housing · heat treatment" /></label>
            <div className="grid gap-3 sm:grid-cols-2"><label htmlFor="new-order-quantity" className={fieldClass}>Order quantity<Input id="new-order-quantity" name="quantity" type="number" min={1} step={1} required value={quantity} onChange={(event) => setQuantity(event.target.value)} placeholder="Enter units" /><span className="text-[10px] font-normal">Whole units only</span></label>
              <label htmlFor="new-order-due" className={fieldClass}>Production due date<Input id="new-order-due" name="dueDate" type="date" required value={dueDate} onChange={(event) => setDueDate(event.target.value)} /><span className="text-[10px] font-normal">When the vendor work must be completed</span></label></div>
            <label htmlFor="new-order-vendor" className={fieldClass}>Assigned vendor<select id="new-order-vendor" name="vendorId" required value={vendorId} onChange={(event) => setVendorId(event.target.value)} className={selectClass}><option value="" disabled>Select an active vendor</option>{activeVendors.map((vendor) => <option key={vendor.id} value={vendor.id}>{vendor.code} · {vendor.name}</option>)}</select></label>
            {!activeVendors.length && <div role="alert" className="flex items-start gap-2 rounded-lg border border-amber-300/70 bg-amber-50/70 p-3 text-xs text-amber-900 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200"><AlertTriangle aria-hidden="true" className="mt-0.5 size-4 shrink-0" /><span>No active vendor is available. Add or reactivate a vendor before creating an order. <Link className="font-semibold underline underline-offset-2" href="/vendors">Go to vendors</Link></span></div>}
          </section>

          <section aria-labelledby="customer-details-heading" className="space-y-3.5 border-t pt-5">
            <div className="flex items-start justify-between gap-3"><div><h3 id="customer-details-heading" className="text-sm font-semibold">Customer demand</h3><p className="mt-0.5 text-[11px] text-muted-foreground">Optional details connect this production work to an outbound order.</p></div><span className="rounded-full border bg-muted/40 px-2 py-1 text-[9px] font-medium text-muted-foreground">Optional</span></div>
            <div className="grid gap-3 sm:grid-cols-2"><label htmlFor="new-order-customer" className={fieldClass}>Customer name<Input id="new-order-customer" name="customerName" value={customerName} onChange={(event) => setCustomerName(event.target.value)} placeholder="Company or customer" /></label><label htmlFor="new-order-customer-order" className={fieldClass}>Customer order number<Input id="new-order-customer-order" name="customerOrderCode" value={customerOrderCode} onChange={(event) => setCustomerOrderCode(event.target.value)} placeholder="e.g. SO-2026-042" /></label></div>
            <label htmlFor="new-order-shipment-due" className={fieldClass}>Customer shipment due date<Input id="new-order-shipment-due" name="shipmentDueDate" type="date" value={shipmentDueDate} onChange={(event) => setShipmentDueDate(event.target.value)} /><span className="text-[10px] font-normal">Leave blank to use the production due date.</span></label>
          </section>

          <section aria-label="Order summary" className="rounded-xl border bg-muted/25 p-4"><div className="mb-3 flex items-center gap-2"><PackageCheck aria-hidden="true" className="size-4 text-primary" /><h3 className="text-xs font-semibold">Order summary</h3></div><div className="grid grid-cols-2 gap-2"><div className="rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">Planned quantity</p><p className="mt-1 text-lg font-semibold tabular-nums">{quantityValid ? formatNumber(parsedQuantity) : "—"}<span className="ml-1 text-[10px] font-normal text-muted-foreground">units</span></p></div><div className="rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">Production due</p><p className="mt-1 flex items-center gap-1.5 text-xs font-semibold">{dueDate ? <><CalendarDays aria-hidden="true" className="size-3.5 text-muted-foreground" />{formatDate(dueDate)}</> : "Not set"}</p></div></div><div className="mt-2 flex items-center gap-2 rounded-lg border bg-background px-3 py-2"><UserRound aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" /><p className="truncate text-xs"><span className="text-muted-foreground">Vendor · </span><span className="font-medium">{selectedVendor?.name ?? "Select a vendor"}</span></p></div>{customerOrderCode && <p className="mt-2 truncate text-[10px] text-muted-foreground">Customer order: <span className="font-medium text-foreground">{customerOrderCode}</span>{customerName ? ` · ${customerName}` : ""}</p>}</section>
        </div>

        <div className="flex flex-col-reverse gap-2 border-t bg-background px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-7"><p className="text-[10px] text-muted-foreground"><span className="text-destructive">*</span> Required fields · You can update order status after creation.</p><div className="flex gap-2"><Button type="button" variant="outline" onClick={() => handleOpenChange(false)}>Cancel</Button><Button type="submit" disabled={!canSubmit}><Plus aria-hidden="true" />Create order</Button></div></div>
      </form>
    </SheetContent>
  </Sheet>;
}

function VendorCreationDrawer({ open, onOpenChange, vendors, onCreate }: { open: boolean; onOpenChange: (open: boolean) => void; vendors: Vendor[]; onCreate: (values: FormData) => boolean }) {
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const [email, setEmail] = useState("");
  const resetDraft = () => { setName(""); setContact(""); setEmail(""); };
  const changeOpen = (next: boolean) => { onOpenChange(next); if (!next) resetDraft(); };
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (onCreate(new FormData(event.currentTarget))) { resetDraft(); onOpenChange(false); }
  };
  const canSubmit = name.trim().length > 0;

  return <Sheet open={open} onOpenChange={changeOpen}>
    <SheetContent aria-describedby="new-vendor-description" className="flex h-dvh w-full max-w-none flex-col gap-0 overflow-hidden p-0 sm:max-w-xl">
      <div className="border-b bg-gradient-to-br from-primary/[0.08] via-background to-background px-5 py-5 pr-14 sm:px-7 sm:py-6">
        <div className="flex items-start gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Factory aria-hidden="true" className="size-5" /></span><div className="min-w-0"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Vendor management</p><SheetTitle className="mt-1 text-xl font-semibold tracking-tight">Add vendor</SheetTitle><SheetDescription id="new-vendor-description" className="sr-only">Add a supplier or subcontractor to the vendor list.</SheetDescription></div></div>
      </div>
      <form onSubmit={submit} className="flex min-h-0 flex-1 flex-col">
        <div className="min-h-0 flex-1 space-y-6 overflow-y-auto px-5 py-5 sm:px-7 sm:py-6">
          <section aria-labelledby="vendor-details-heading" className="space-y-3.5">
            <div className="flex items-start justify-between gap-3"><div><h3 id="vendor-details-heading" className="text-sm font-semibold">Company details</h3><p className="mt-0.5 text-[11px] text-muted-foreground">Add the supplier contact used for production coordination.</p></div><span className="rounded-full border bg-muted/40 px-2 py-1 text-[9px] font-medium text-muted-foreground">Required</span></div>
            <label htmlFor="new-vendor-name" className={fieldClass}>Company name<Input autoFocus id="new-vendor-name" name="name" required value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Apex Heat Treatment Works" /></label>
            <label htmlFor="new-vendor-contact" className={fieldClass}>Contact person<Input id="new-vendor-contact" name="contact" required value={contact} onChange={(event) => setContact(event.target.value)} placeholder="Primary vendor contact" /></label>
            <label htmlFor="new-vendor-email" className={fieldClass}>Email address<Input id="new-vendor-email" name="email" type="email" required value={email} onChange={(event) => setEmail(event.target.value)} placeholder="name@company.com" /></label>
          </section>
          <section aria-label="Vendor record preview" className="rounded-xl border bg-muted/25 p-4"><div className="mb-3 flex items-center gap-2"><UserRound aria-hidden="true" className="size-4 text-primary" /><h3 className="text-xs font-semibold">Vendor record</h3></div><div className="grid grid-cols-2 gap-2"><div className="rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">Vendor code</p><p className="mt-1 text-sm font-semibold">{nextVendorCode(vendors)}</p></div><div className="rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">Initial status</p><p className="mt-1 text-sm font-semibold text-emerald-700">Active</p></div></div><p className="mt-2 truncate text-xs text-muted-foreground">{name.trim() || "Company name"}{contact.trim() ? ` · ${contact.trim()}` : ""}</p></section>
        </div>
        <div className="flex flex-col-reverse gap-2 border-t bg-background px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-7"><p className="text-[10px] text-muted-foreground"><span className="text-destructive">*</span> Required fields · Vendor code is assigned automatically.</p><div className="flex gap-2"><Button type="button" variant="outline" onClick={() => changeOpen(false)}>Cancel</Button><Button type="submit" disabled={!canSubmit}><Plus aria-hidden="true" />Add vendor</Button></div></div>
      </form>
    </SheetContent>
  </Sheet>;
}

function ReceiptCreationDrawer({ open, onOpenChange, orders, data, onCreate }: { open: boolean; onOpenChange: (open: boolean) => void; orders: ProductionOrder[]; data: ForgeData; onCreate: (values: FormData) => boolean }) {
  const receivableOrders = orders.filter((order) => {
    const dispatched = data.dispatches.filter((item) => item.orderId === order.id).reduce((sum, item) => sum + item.quantity, 0);
    const received = data.receipts.filter((item) => item.orderId === order.id).reduce((sum, item) => sum + item.quantity, 0);
    return dispatched > received;
  });
  const [orderId, setOrderId] = useState(receivableOrders[0]?.id ?? "");
  const [quantityText, setQuantityText] = useState("");
  const order = receivableOrders.find((item) => item.id === orderId);
  const flow = order ? calculateOrderFlow(data, order) : null;
  const vendor = order ? data.vendors.find((item) => item.id === order.vendorId) : undefined;
  const capacity = flow ? Math.max(0, flow.dispatched - flow.received) : 0;
  const quantity = Number(quantityText);
  const quantityValid = quantityText.trim() !== "" && Number.isSafeInteger(quantity) && quantity > 0 && quantity <= capacity;
  const projectedReceived = flow && quantityValid ? flow.received + quantity : flow?.received ?? 0;
  const reportBalance = flow ? Math.max(0, flow.reported - projectedReceived) : 0;
  const receiptVariance = flow && flow.reported > 0 ? projectedReceived - flow.reported : 0;
  const resetDraft = () => { setOrderId(receivableOrders[0]?.id ?? ""); setQuantityText(""); };
  const changeOpen = (next: boolean) => { onOpenChange(next); if (!next) resetDraft(); };
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (onCreate(new FormData(event.currentTarget))) { resetDraft(); onOpenChange(false); } };
  const metric = (label: string, value: number) => <div className="rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-0.5 text-sm font-semibold tabular-nums">{formatNumber(value)}</p></div>;

  return <Sheet open={open} onOpenChange={changeOpen}>
    <SheetContent aria-describedby="new-receipt-description" className="flex h-dvh w-full max-w-none flex-col gap-0 overflow-hidden p-0 sm:max-w-xl">
      <div className="border-b bg-gradient-to-br from-primary/[0.08] via-background to-background px-5 py-5 pr-14 sm:px-7 sm:py-6"><div className="flex items-start gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Boxes aria-hidden="true" className="size-5" /></span><div className="min-w-0"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Warehouse receiving</p><SheetTitle className="mt-1 text-xl font-semibold tracking-tight">New goods receipt</SheetTitle><SheetDescription id="new-receipt-description" className="mt-1 text-xs leading-5">Record the quantity physically counted at the warehouse against a vendor dispatch.</SheetDescription></div></div></div>
      <form onSubmit={submit} className="flex min-h-0 flex-1 flex-col">
        <div className="min-h-0 flex-1 space-y-5 overflow-y-auto px-5 py-5 sm:px-7 sm:py-6">
          {receivableOrders.length ? <>
            <section aria-labelledby="receipt-details-heading" className="space-y-3.5"><div className="flex items-start justify-between gap-3"><div><h3 id="receipt-details-heading" className="text-sm font-semibold">Incoming vendor return</h3><p className="mt-0.5 text-[11px] text-muted-foreground">Select the order on the delivery documents, then count the units received.</p></div><span className="rounded-full border bg-muted/40 px-2 py-1 text-[9px] font-medium text-muted-foreground">Required</span></div>
              <label htmlFor="receipt-order" className={fieldClass}>Production order<select id="receipt-order" name="orderId" required value={orderId} onChange={(event) => { setOrderId(event.target.value); setQuantityText(""); }} className={selectClass}><option value="" disabled>Select an order</option>{receivableOrders.map((item) => { const orderFlow = calculateOrderFlow(data, item); const remaining = Math.max(0, orderFlow.dispatched - orderFlow.received); return <option key={item.id} value={item.id}>{item.code} · {item.product} · {formatNumber(remaining)} awaiting receipt</option>; })}</select></label>
              {order && flow && <div className="rounded-xl border bg-muted/25 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-xs font-semibold">{order.code}</p><p className="mt-1 text-[11px] text-muted-foreground">{order.product} · {vendor?.name ?? "Unknown vendor"}</p></div><Link href={`/orders/${order.id}`} className="text-[11px] font-medium text-primary hover:underline">View order <ArrowRight className="inline size-3" /></Link></div><div className="mt-3 grid grid-cols-2 gap-2">{metric("Order quantity", order.quantity)}{metric("Dispatched", flow.dispatched)}{metric("Already received", flow.received)}{metric("Available to receive", capacity)}{metric("Vendor reported returned", flow.reported)}{metric("Accepted so far", flow.accepted)}</div></div>}
              <label htmlFor="receipt-quantity" className={fieldClass}>Quantity physically received<Input id="receipt-quantity" name="quantity" type="number" min={1} max={capacity || undefined} step={1} required value={quantityText} onChange={(event) => setQuantityText(event.target.value)} placeholder="Count the delivered units" /><span className="text-[10px] font-normal">Enter the count from this delivery only. You can record a partial return.</span></label>
              {quantityText && Number.isSafeInteger(quantity) && quantity > capacity && <p role="alert" className="-mt-2 text-xs text-destructive">This exceeds the {formatNumber(capacity)} units dispatched and not yet received.</p>}
            </section>
            {flow && quantityValid && <section aria-label="Receipt quantity check" aria-live="polite" className="rounded-xl border bg-muted/25 p-4"><div className="flex items-center justify-between gap-3"><div><h3 className="text-xs font-semibold">After this receipt</h3><p className="mt-1 text-[10px] text-muted-foreground">Cumulative physical receipt compared with the latest vendor report.</p></div><p className="text-sm font-semibold tabular-nums">{formatNumber(projectedReceived)} received</p></div>{flow.reported > 0 && <p className="mt-3 text-[11px] text-muted-foreground">{reportBalance > 0 ? `${formatNumber(reportBalance)} vendor-reported unit(s) would still be unreceived.` : receiptVariance > 0 ? `Warehouse count would be ${formatNumber(receiptVariance)} above the vendor report; verify the paperwork and record the physical count.` : "The reported quantity would be fully received."}</p>}</section>}
            {flow && flow.overReported > 0 && <div role="alert" className="flex items-start gap-2 rounded-lg border border-amber-300/70 bg-amber-50/70 p-3 text-[11px] leading-4 text-amber-900 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200"><AlertTriangle aria-hidden="true" className="mt-0.5 size-4 shrink-0" /><p>Vendor report is {formatNumber(flow.overReported)} above the quantity dispatched. This receipt remains capped by the physical dispatched balance. Keep the report for follow-up; do not adjust the count to match it.</p></div>}
            <div className="flex items-start gap-2 rounded-lg border border-blue-200/70 bg-blue-50/60 p-3 text-[11px] leading-4 text-blue-900 dark:border-blue-900 dark:bg-blue-950/30 dark:text-blue-200"><CircleAlert aria-hidden="true" className="mt-0.5 size-4 shrink-0" /><p>Record only units that have arrived and been counted. Quality inspection is a separate step after saving this receipt.</p></div>
          </> : <div className="rounded-xl border border-dashed p-6 text-center"><span className="mx-auto flex size-10 items-center justify-center rounded-xl bg-muted text-muted-foreground"><Boxes aria-hidden="true" className="size-5" /></span><p className="mt-3 text-sm font-semibold">No dispatched units awaiting receipt</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Record a vendor dispatch first. A vendor-reported return is not warehouse stock until the goods physically arrive and are counted.</p><Button className="mt-4" type="button" variant="outline" asChild><Link href="/orders">Open production orders <ArrowRight className="size-3.5" /></Link></Button></div>}
        </div>
        <div className="flex flex-col-reverse gap-2 border-t bg-background px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-7"><p className="text-[10px] text-muted-foreground">A goods receipt number is assigned automatically when saved.</p><div className="flex gap-2"><Button type="button" variant="outline" onClick={() => changeOpen(false)}>Cancel</Button><Button type="submit" disabled={!order || !quantityValid}><Plus aria-hidden="true" />Record receipt</Button></div></div>
      </form>
    </SheetContent>
  </Sheet>;
}

export function WorkspacePage({ section, recordId }: { section: Section; recordId?: string }) {
  const { data, ready, update, refresh, reset } = useForge();
  const [query, setQuery] = useState("");
  const [showForm, setShowForm] = useState(false);
  const [historyPage, setHistoryPage] = useState(1);
  const [expandedHistoryDetails, setExpandedHistoryDetails] = useState<string[]>([]);
  const [reconciliationStatus, setReconciliationStatus] = useState<"All" | "Open" | "Resolved">("Open");
  const [resolvingId, setResolvingId] = useState<string | null>(null);
  const [resolutionDraft, setResolutionDraft] = useState("");
  const [csv, setCsv] = useState("externalId,vendorCode,orderCode,reportedQty\nEXT-001,VND-101,PO-2026-1001,500");
  const [importError, setImportError] = useState("");
  const [integrationUnavailable, setIntegrationUnavailable] = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);
  const [importFile, setImportFile] = useState("vendor-updates.csv");
  const [today, setToday] = useState<string | null>(null);
  const [updatedAt, setUpdatedAt] = useState<string | null>(null);
  const [range, setRange] = useState<DashboardRange>("30d");
  useEffect(() => { const frame = window.requestAnimationFrame(() => { const now = new Date(); setToday(toDateInputValue(now)); setUpdatedAt(now.toLocaleTimeString("en-IN", { hour: "numeric", minute: "2-digit" })); }); return () => window.cancelAnimationFrame(frame); }, []);
  const foundOrder = data.orders.find((x) => x.id === recordId);
  const foundVendor = data.vendors.find((x) => x.id === recordId);
  const search = (value: string) => value.toLowerCase().includes(query.toLowerCase());
  const uninspectedReceipts = data.receipts.filter((r) => !data.inspections.some((i) => i.receiptId === r.id));
  const totals = useMemo(() => ({
    active: data.orders.filter((x) => ["Pending", "In Progress", "Blocked"].includes(x.status)).length,
    due: today ? data.orders.filter((x) => x.dueDate < today && !["Completed", "Shipped"].includes(x.status)).length : 0,
    openReconciliation: data.reconciliations.filter((x) => x.status === "Open").length,
    received: data.receipts.reduce((n, x) => n + x.quantity, 0),
    deliveryShortfall: data.orders.reduce((n, order) => n + calculateOrderFlow(data, order).remainingToShip, 0),
    invoiceVariance: data.orders.reduce((n, order) => { const flow = calculateOrderFlow(data, order); return n + Math.abs(flow.invoiced - flow.received); }, 0),
  }), [data, today]);
  const vendorName = (id: string) => data.vendors.find((x) => x.id === id)?.name ?? "Unknown vendor";
  const orderName = (id: string) => data.orders.find((x) => x.id === id)?.code ?? "Unknown order";
  const receiptRows = data.receipts.filter((r) => [r.reference, orderName(r.orderId), vendorName(r.vendorId)].some(search));
  const inspectionRows = data.inspections.filter((i) => { const receipt = data.receipts.find((item) => item.id === i.receiptId); return [i.id, i.notes, receipt?.reference ?? "", receipt ? orderName(receipt.orderId) : ""].some(search); });
  const receiptUnits = data.receipts.reduce((total, receipt) => total + receipt.quantity, 0);
  const uninspectedUnits = uninspectedReceipts.reduce((total, receipt) => total + receipt.quantity, 0);
  const receiptFor = (orderId: string) => data.receipts.filter((x) => x.orderId === orderId).reduce((n, x) => n + x.quantity, 0);
  const acceptedFor = (orderId: string) => data.receipts.filter((x) => x.orderId === orderId).reduce((n, r) => n + data.inspections.filter((i) => i.receiptId === r.id).reduce((m, i) => m + i.accepted, 0), 0);
  const latestQuantityGapCount = latestReconciliations(data.reconciliations).filter((report) => {
    const progress = calculateReconciliationProgress(data, report);
    return progress && report.reported !== progress.received;
  }).length;
  const matchingHistory = [...data.history].filter((item) => [item.action, item.detail].some(search)).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const historyPageSize = 20;
  const historyPageCount = Math.max(1, Math.ceil(matchingHistory.length / historyPageSize));
  const currentHistoryPage = Math.min(historyPage, historyPageCount);
  const historyStart = (currentHistoryPage - 1) * historyPageSize;
  const pagedHistory = matchingHistory.slice(historyStart, historyStart + historyPageSize);

  const addOrder = (f: FormData): boolean => {
    const id = makeId("ord"); const dueDate = String(f.get("dueDate"));
    const order: ProductionOrder = { id, code: `PO-${new Date().getFullYear()}-${id.slice(-6).toUpperCase()}`, product: String(f.get("product")).trim(), quantity: Number(f.get("quantity")), dueDate, vendorId: String(f.get("vendorId")), status: "Pending", createdAt: new Date().toISOString(), customerOrderCode: String(f.get("customerOrderCode") ?? "").trim(), customerName: String(f.get("customerName") ?? "").trim(), shipmentDueDate: String(f.get("shipmentDueDate") ?? "") || dueDate };
    if (!order.product || !Number.isSafeInteger(order.quantity) || order.quantity < 1 || !order.dueDate || !order.vendorId || !data.vendors.some((vendor) => vendor.id === order.vendorId && vendor.status === "Active")) { toast.error("Add a product, valid quantity, production due date, and active vendor."); return false; }
    update((d) => ({ ...d, orders: [order, ...d.orders] }), "Production order created", `${order.code} · ${order.product} · ${formatNumber(order.quantity)} units`); toast.success(`${order.code} created`); setShowForm(false); return true;
  };
  const addVendor = (f: FormData): boolean => {
    const vendor: Vendor = { id: makeId("ven"), code: nextVendorCode(data.vendors), name: String(f.get("name")).trim(), contact: String(f.get("contact")).trim(), email: String(f.get("email")).trim(), status: "Active" };
    if (!vendor.code || !vendor.name || !vendor.contact || !vendor.email) { toast.error("Company name, contact person, and email are required."); return false; }
    if (data.vendors.some((x) => x.code.toLowerCase() === vendor.code.toLowerCase())) { toast.error("That vendor code already exists."); return false; }
    update((d) => ({ ...d, vendors: [vendor, ...d.vendors] }), "Vendor added", `${vendor.code} · ${vendor.name}`); toast.success("Vendor added"); setShowForm(false); return true;
  };
  const addReceipt = (f: FormData): boolean => {
    const orderId = String(f.get("orderId"));
    const result = recordReceipt(data, orderId, Number(f.get("quantity")));
    if (!result.ok) { toast.error(result.error); return false; }
    const receipt = result.value.receipts[0]; const order = data.orders.find((x) => x.id === orderId)!;
    update((d) => ({ ...d, receipts: [receipt, ...d.receipts], orders: d.orders.map((x) => x.id === order.id && x.status === "Pending" ? { ...x, status: "In Progress" } : x) }), "Warehouse receipt recorded", receipt.reference + " · " + order.code + " · " + formatNumber(receipt.quantity) + " units"); toast.success("Receipt recorded"); return true;
  };
  const addInspection = (f: FormData): boolean => {
    const receiptId = String(f.get("receiptId"));
    const result = recordInspection(data, receiptId, Number(f.get("accepted")), Number(f.get("rejected")), String(f.get("notes") ?? ""));
    if (!result.ok) { toast.error(result.error); return false; }
    const inspection = result.value.inspections[0]; const receipt = data.receipts.find((x) => x.id === receiptId)!;
    update((d) => ({ ...d, inspections: [inspection, ...d.inspections] }), "Quality inspection completed", orderName(receipt.orderId) + " · " + formatNumber(inspection.accepted) + " accepted · " + formatNumber(inspection.rejected) + " rejected"); toast.success("Inspection saved"); return true;
  };
  const addDispatch = (orderId: string, f: FormData) => {
    const result = recordDispatch(data, orderId, Number(f.get("quantity")));
    if (!result.ok) { toast.error(result.error); return false; }
    const record = result.value.dispatches[0];
    update((d) => ({ ...d, dispatches: [record, ...d.dispatches], orders: d.orders.map((x) => x.id === orderId && x.status === "Pending" ? { ...x, status: "In Progress" } : x) }), "Components dispatched to vendor", `${record.reference} · ${formatNumber(record.quantity)} units`);
    toast.success("Vendor dispatch recorded"); return true;
  };
  const addInvoice = (orderId: string, f: FormData) => {
    const result = recordInvoice(data, orderId, Number(f.get("quantity")), undefined, undefined, String(f.get("supplierReference") ?? ""));
    if (!result.ok) { toast.error(result.error); return false; }
    const record = result.value.invoices[0];
    update((d) => ({ ...d, invoices: [record, ...d.invoices] }), "Vendor invoice recorded", `${record.reference} · ${formatNumber(record.quantity)} units billed`);
    toast.success("Vendor invoice recorded"); return true;
  };
  const addShipment = (orderId: string, f: FormData) => {
    const result = recordShipment(data, orderId, Number(f.get("quantity")));
    if (!result.ok) { toast.error(result.error); return false; }
    const record = result.value.shipments[0];
    const shipped = data.shipments.filter((x) => x.orderId === orderId).reduce((n, x) => n + x.quantity, 0) + record.quantity;
    const order = data.orders.find((x) => x.id === orderId)!;
    update((d) => ({ ...d, shipments: [record, ...d.shipments], orders: d.orders.map((x) => x.id === orderId && shipped >= order.quantity ? { ...x, status: "Shipped" } : x) }), "Customer shipment recorded", `${record.reference} · ${formatNumber(record.quantity)} units shipped`);
    toast.success("Customer shipment recorded"); return true;
  };
  const addReconciliation = (f: FormData): boolean => {
    const order = data.orders.find((x) => x.id === f.get("orderId")); if (!order) { toast.error("Select an order."); return false; }
    const reported = Number(f.get("reported")); if (!Number.isSafeInteger(reported) || reported < 0) { toast.error("Reported quantity must be a non-negative whole number."); return false; }
    const flow = calculateOrderFlow(data, order);
    const rec = { id: makeId("rec"), orderId: order.id, vendorId: order.vendorId, reported, dispatched: flow.dispatched, received: flow.received, accepted: flow.accepted, invoiced: flow.invoiced, status: "Open" as const, createdAt: new Date().toISOString() };
    update((d) => ({ ...d, reconciliations: [rec, ...d.reconciliations] }), "Reconciliation opened", `${order.code} · vendor reported ${formatNumber(reported)}, warehouse received ${formatNumber(rec.received)}, accepted ${formatNumber(rec.accepted)}`); toast.success("Reconciliation opened"); return true;
  };
  const resolveReconciliation = (id: string) => {
    const note = resolutionDraft.trim();
    const item = data.reconciliations.find((entry) => entry.id === id);
    if (!item || item.status !== "Open") { toast.error("This report is no longer open. Refresh the list and review its current status."); return; }
    if (!note) { toast.error("Add the agreed outcome or next action before resolving."); return; }
    update((d) => ({ ...d, reconciliations: d.reconciliations.map((entry) => entry.id === id && entry.status === "Open" ? { ...entry, status: "Resolved", resolutionNote: note, resolvedAt: new Date().toISOString() } : entry) }), "Reconciliation resolved", `${orderName(item.orderId)} · ${note}`);
    setResolvingId(null); setResolutionDraft(""); toast.success("Report resolved with an audit note");
  };

  function processImport(payload: string, fileName: string, simulateOutage = false) {
    if (payload.length > 1_500_000) { setImportError("CSV is larger than the 1.5 MB local demo limit."); return; }
    const preview = previewVendorUpdateImport(data, payload, simulateOutage);
    if (!preview.ok) { setImportError(preview.error); return; }
    if (preview.rows > 10000) { setImportError("A batch is limited to 10,000 data rows in this local demo."); return; }
    const now = new Date().toISOString();
    const newReconciliations: ForgeData["reconciliations"] = preview.accepted.map((item) => {
      const order = data.orders.find((candidate) => candidate.id === item.orderId)!;
      const flow = calculateOrderFlow(data, order);
      return { id: makeId("rec"), orderId: item.orderId, vendorId: item.vendorId, reported: item.reported, dispatched: flow.dispatched, received: flow.received, accepted: flow.accepted, invoiced: flow.invoiced, status: "Open", createdAt: now, externalId: item.externalId };
    });
    const retryPayload = preview.failedRows.length ? [preview.headers, ...preview.failedRows].map(serializeCsvRow).join("\n") : "";
    const batch = { id: makeId("batch"), fileName: fileName.trim() || "vendor-updates.csv", importedAt: now, rows: preview.rows, accepted: preview.accepted.length, skipped: preview.skipped, failed: preview.failedRows.length, payload: retryPayload, externalIds: preview.accepted.map((item) => normalizeExternalId(item.externalId)), failureDetails: preview.failureDetails };
    update((d) => ({ ...d, reconciliations: [...newReconciliations, ...d.reconciliations], imports: [batch, ...d.imports] }), "Vendor updates imported", batch.fileName + " · " + batch.accepted + " accepted · " + batch.skipped + " duplicate · " + batch.failed + " failed");
    setImportError(""); setCsv("externalId,vendorCode,orderCode,reportedQty\n");
    if (batch.failed) toast.warning("Import finished with " + batch.failed + " row(s) to retry."); else toast.success("Import finished: " + batch.accepted + " accepted, " + batch.skipped + " duplicates skipped.");
  }

  if (!ready) return <div className="space-y-5"><PageHeader title={titles[section][0]} description={titles[section][1]} /><div className="animate-pulse rounded-xl border bg-card p-10 text-sm text-muted-foreground">Loading your workspace…</div></div>;
  const headerActions = section === "orders" || section === "vendors" || section === "receipts" || section === "quality" || section === "reconciliation" ? <Button onClick={() => setShowForm((v) => !v)}><Plus />{showForm ? "Close form" : `New ${section === "orders" ? "order" : section === "vendors" ? "vendor" : section === "receipts" ? "receipt" : section === "quality" ? "inspection" : "reconciliation"}`}</Button> : undefined;

  return <div className="space-y-6">
    {section === "dashboard" ? <DashboardToolbar updatedAt={updatedAt} range={range} setRange={setRange} onRefresh={() => { const now = new Date(); setToday(toDateInputValue(now)); setUpdatedAt(now.toLocaleTimeString("en-IN", { hour: "numeric", minute: "2-digit" })); if (refresh()) toast.success("Dashboard data refreshed from this browser"); else toast.error("Could not read saved workspace data"); }} /> : <PageHeader title={section === "order" && foundOrder ? foundOrder.code : section === "vendor" && foundVendor ? foundVendor.name : titles[section][0]} description={titles[section][1]} actions={headerActions} />}
    {section === "dashboard" && <Dashboard data={data} totals={totals} vendorName={vendorName} today={today} range={range} />}
    {section === "orders" && <>
      <OrderCreationDrawer open={showForm} onOpenChange={setShowForm} vendors={data.vendors} onCreate={addOrder} />
      <SearchBox query={query} setQuery={setQuery} placeholder="Search order, product, vendor…" />
      <TableWrap headers={["Order", "Product", "Vendor", "Quantity", "Due date", "Received", "Status", "Actions"]}>{data.orders.filter((x) => [x.code, x.product, vendorName(x.vendorId), x.status].some(search)).map((o, index) => <OrderRow key={o.id} serialNumber={index + 1} order={o} vendor={vendorName(o.vendorId)} received={receiptFor(o.id)} update={update} hasLinkedData={data.dispatches.some((d) => d.orderId === o.id) || data.receipts.some((r) => r.orderId === o.id) || data.invoices.some((i) => i.orderId === o.id) || data.shipments.some((s) => s.orderId === o.id) || data.reconciliations.some((r) => r.orderId === o.id)} today={today} />)}</TableWrap>
      {!data.orders.length && <Empty>No orders yet. Create one to start tracking production.</Empty>}
    </>}
    {section === "order" && (foundOrder ? <><OrderWorkflow order={foundOrder} data={data} today={today} onDispatch={addDispatch} onInvoice={addInvoice} onShipment={addShipment} /><OrderDetail order={foundOrder} data={data} vendorName={vendorName(foundOrder.vendorId)} receipts={data.receipts.filter((x) => x.orderId === foundOrder.id)} inspections={data.inspections} update={update} receiptFor={receiptFor(foundOrder.id)} accepted={acceptedFor(foundOrder.id)} /></> : <Empty>That order no longer exists. <Link className="text-primary underline" href="/orders">Return to orders</Link></Empty>)}
    {section === "vendors" && <>
      <VendorCreationDrawer open={showForm} onOpenChange={setShowForm} vendors={data.vendors} onCreate={addVendor} />
      <SearchBox query={query} setQuery={setQuery} placeholder="Search vendor, code, contact…" />
      <TableWrap headers={["Vendor", "Contact", "Email", "Open orders", "Status", "Actions"]}>{data.vendors.filter((x) => [x.code, x.name, x.contact, x.email].some(search)).map((v) => { const linked = data.orders.some((o) => o.vendorId === v.id); return <Row key={v.id}><Cell><Link className="font-medium text-primary hover:underline" href={`/vendors/${v.id}`}>{v.name}</Link><div className="text-xs text-muted-foreground">{v.code}</div></Cell><Cell>{v.contact}</Cell><Cell>{v.email}</Cell><Cell>{data.orders.filter((o) => o.vendorId === v.id && !["Completed", "Shipped"].includes(o.status)).length}</Cell><Cell><StatusBadge status={v.status} /></Cell><Cell><div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => update((d) => ({ ...d, vendors: d.vendors.map((x) => x.id === v.id ? { ...x, status: x.status === "Active" ? "On Hold" : "Active" } : x) }), "Vendor status changed", `${v.name} set to ${v.status === "Active" ? "On Hold" : "Active"}`)}>{v.status === "Active" ? "Place on hold" : "Reactivate"}</Button><Button size="sm" variant="ghost" title={linked ? "Remove linked orders before deleting this vendor" : "Delete vendor"} disabled={linked} onClick={() => { if (window.confirm(`Delete ${v.name}?`)) update((d) => ({ ...d, vendors: d.vendors.filter((x) => x.id !== v.id) }), "Vendor deleted", `${v.code} · ${v.name}`); }}><Trash2 className="size-4" /></Button></div></Cell></Row>; })}</TableWrap>
      {!data.vendors.length && <Empty>Add vendors before creating a production order.</Empty>}
    </>}
    {section === "vendor" && (foundVendor ? <VendorDetail vendor={foundVendor} data={data} update={update} /> : <Empty>That vendor could not be found. <Link className="text-primary underline" href="/vendors">Return to vendors</Link></Empty>)}
    {section === "receipts" && <>
      <ReceiptCreationDrawer open={showForm} onOpenChange={setShowForm} orders={data.orders} data={data} onCreate={addReceipt} />
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <SearchBox query={query} setQuery={setQuery} placeholder="Search receipt, order, vendor…" />
        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground" aria-live="polite">
          <span><strong className="font-semibold text-foreground">{data.receipts.length}</strong> receipts</span>
          <span><strong className="font-semibold text-foreground">{formatNumber(receiptUnits)}</strong> units received</span>
          <span className={uninspectedReceipts.length ? "text-amber-700 dark:text-amber-400" : ""}><strong className="font-semibold">{uninspectedReceipts.length}</strong> awaiting inspection · {formatNumber(uninspectedUnits)} units</span>
        </div>
      </div>
      {receiptRows.length ? <TableWrap headers={["Receipt reference", "Production order", "Vendor", "Received date", "Quantity", "Quality status"]}>{receiptRows.map((r) => { const insp = data.inspections.find((x) => x.receiptId === r.id); return <Row key={r.id}><Cell className="font-medium">{r.reference}</Cell><Cell><Link href={`/orders/${r.orderId}`} className="font-medium text-primary hover:underline">{orderName(r.orderId)}</Link></Cell><Cell>{vendorName(r.vendorId)}</Cell><Cell>{formatDate(r.receivedAt)}</Cell><Cell className="tabular-nums">{formatNumber(r.quantity)} <span className="text-xs text-muted-foreground">units</span></Cell><Cell>{insp ? <StatusBadge status={`${formatNumber(insp.accepted)} accepted · ${formatNumber(insp.rejected)} rejected`} /> : <StatusBadge status="Pending inspection" className="border-amber-200 bg-amber-100 text-amber-800" />}</Cell></Row>; })}</TableWrap> : <div className={`${panelClass} border-dashed shadow-none`}><Empty>{data.receipts.length ? "No receipts match this search. Try a receipt reference, order number, or vendor." : "No goods have been received yet. Record the vendor delivery here, then send each receipt to Quality for inspection."}</Empty>{!data.receipts.length && <div className="flex justify-center pb-5"><Button variant="outline" asChild><Link href="/quality">How quality inspection works <ArrowRight className="size-4" /></Link></Button></div>}</div>}
    </>}
    {section === "quality" && <>
      <QualityInspectionForm open={showForm} onOpenChange={setShowForm} receipts={uninspectedReceipts} data={data} onSubmit={addInspection} />
      <section aria-label="Quality inspection summary" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><KpiTile label="Receipts awaiting inspection" value={uninspectedReceipts.length} icon={ShieldAlert} definition="Each pending receipt needs one inspection before its units become accepted stock." warn={uninspectedReceipts.length > 0} /><KpiTile label="Units awaiting inspection" value={formatNumber(uninspectedUnits)} icon={ActivityIcon} definition="Physical units on receipts that have not been inspected yet." warn={uninspectedUnits > 0} /><KpiTile label="Accepted stock" value={formatNumber(data.inspections.reduce((total, inspection) => total + inspection.accepted, 0))} icon={Check} definition="Units that passed inspection and can be used for customer shipments." /><KpiTile label="Rejected / held" value={formatNumber(data.inspections.reduce((total, inspection) => total + inspection.rejected, 0))} icon={AlertTriangle} definition="Units excluded from available stock because they failed inspection." warn={data.inspections.some((inspection) => inspection.rejected > 0)} /></section>
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><SearchBox query={query} setQuery={setQuery} placeholder="Search receipt, order, inspection, or notes" /><p className="text-xs text-muted-foreground">{data.inspections.length} completed inspection{data.inspections.length === 1 ? "" : "s"}</p></div>
      {inspectionRows.length ? <TableWrap headers={["Inspection", "Receipt", "Order", "Accepted", "Rejected / held", "Findings / disposition", "Inspected"]}>{inspectionRows.map((i) => { const r = data.receipts.find((x) => x.id === i.receiptId); return <Row key={i.id}><Cell className="font-mono text-xs">{i.id.slice(-8)}</Cell><Cell className="font-medium">{r?.reference ?? "Deleted receipt"}</Cell><Cell>{r ? <Link href={`/orders/${r.orderId}`} className="text-primary hover:underline">{orderName(r.orderId)}</Link> : "—"}</Cell><Cell className="tabular-nums text-emerald-700">{formatNumber(i.accepted)}</Cell><Cell className="tabular-nums text-rose-700">{formatNumber(i.rejected)}</Cell><Cell className="max-w-sm truncate" title={i.notes}>{i.notes || "—"}</Cell><Cell>{formatDate(i.inspectedAt)}</Cell></Row>; })}</TableWrap> : <div className={`${panelClass} border-dashed shadow-none`}><Empty>{data.inspections.length ? "No inspections match this search. Try a receipt reference, order number, or note." : "There are no inspections yet. Record a warehouse receipt first, then classify every received unit here."}</Empty>{!data.inspections.length && <div className="flex justify-center pb-5"><Button variant="outline" asChild><Link href="/warehouse/receipts">Go to warehouse receipts <ArrowRight className="size-4" /></Link></Button></div>}</div>}
    </>}
    {section === "reconciliation" && <>
      <ReconciliationForm open={showForm} onOpenChange={setShowForm} orders={data.orders} data={data} onSubmit={addReconciliation} />
      <section aria-label="Reconciliation summary" className="grid gap-3 sm:grid-cols-3"><ReconciliationSummary label="Open reports" value={data.reconciliations.filter((item) => item.status === "Open").length} detail="Need an investigation or documented next step" /><ReconciliationSummary label="Orders with a latest quantity gap" value={latestQuantityGapCount} detail="Latest vendor report compared with current warehouse receipts" /><ReconciliationSummary label="Resolved reports" value={data.reconciliations.filter((item) => item.status === "Resolved").length} detail="Resolution note recorded in activity history" /></section>
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="max-w-md flex-1"><SearchBox query={query} setQuery={setQuery} placeholder="Search order, vendor, or report reference" /></div><label className="grid gap-1 text-xs font-medium text-muted-foreground">Status<select className={`${selectClass} sm:w-44`} value={reconciliationStatus} onChange={(event) => setReconciliationStatus(event.target.value as "All" | "Open" | "Resolved")}><option>Open</option><option>Resolved</option><option>All</option></select></label></div>
      <ReconciliationList data={data} query={query} status={reconciliationStatus} resolvingId={resolvingId} resolutionDraft={resolutionDraft} onResolveOpen={(id) => { setResolvingId(id); setResolutionDraft(""); }} onResolutionChange={setResolutionDraft} onCancelResolve={() => { setResolvingId(null); setResolutionDraft(""); }} onResolve={resolveReconciliation} />
    </>}
    {section === "imports" && <>
      <div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]">
        <section className={panelClass}><div className="mb-3 flex items-center gap-2"><FileUp className="size-4" /><h2 className="font-semibold">Import vendor updates</h2></div><p className="mb-4 text-sm text-muted-foreground">Paste CSV below or choose a .csv file. Required columns: <code>externalId,vendorCode,orderCode,reportedQty</code>. Each valid row opens a reconciliation record.</p><div className="space-y-3"><Field label="Source file name"><Input value={importFile} onChange={(e) => setImportFile(e.target.value)} /></Field><textarea aria-label="CSV vendor updates" value={csv} onChange={(e) => setCsv(e.target.value)} className="min-h-36 w-full rounded-md border border-input bg-background p-3 font-mono text-xs focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring" /><label className="flex cursor-pointer items-center gap-2 text-sm"><input type="checkbox" checked={integrationUnavailable} onChange={(e) => setIntegrationUnavailable(e.target.checked)} />Simulate vendor integration outage</label>{integrationUnavailable && <p className="text-xs text-amber-700">Imports will be held as retryable failures until the outage toggle is turned off.</p>}<div className="flex flex-wrap gap-2"><label className="inline-flex h-9 cursor-pointer items-center gap-2 rounded-md border px-3 text-sm hover:bg-muted"><ArrowDownToLine className="size-4" />Choose CSV<input type="file" accept=".csv,text/csv" className="sr-only" onChange={(e) => { const file = e.target.files?.[0]; if (file) { setImportFile(file.name); void file.text().then(setCsv).catch(() => { setImportError("The selected CSV could not be read."); }); } }} /></label><Button onClick={() => processImport(csv, importFile, integrationUnavailable)}><FileUp />Run import</Button><Button variant="outline" onClick={() => setCsv("externalId,vendorCode,orderCode,reportedQty\nEXT-001,VND-101,PO-2026-1001,500\nEXT-002,VND-999,PO-2026-1001,450")}>Load sample CSV</Button></div>{importError && <p role="alert" className="text-sm text-destructive">{importError}</p>}</div></section>
        <section className={panelClass}><h2 className="mb-3 font-semibold">Import rules</h2><ul className="space-y-3 text-sm text-muted-foreground"><li className="flex gap-2"><Check className="size-4 shrink-0 text-emerald-600" />Validate vendor, order, and integer quantity.</li><li className="flex gap-2"><Check className="size-4 shrink-0 text-emerald-600" />Skip repeated external IDs, including earlier batches.</li><li className="flex gap-2"><AlertTriangle className="size-4 shrink-0 text-amber-600" />Keep invalid rows for retry after fixing the vendor or order code.</li><li className="flex gap-2"><ActivityIcon className="size-4 shrink-0 text-primary" />Accepted updates open reconciliation records and appear in history.</li></ul></section>
      </div>
      <TableWrap headers={["Batch", "Imported", "Rows", "Accepted", "Skipped", "Failed", "Action"]}>{data.imports.map((b) => <Row key={b.id}><Cell className="font-medium">{b.fileName}</Cell><Cell>{formatDate(b.importedAt)}</Cell><Cell>{b.rows}</Cell><Cell>{b.accepted}</Cell><Cell>{b.skipped}</Cell><Cell title={b.failureDetails?.join("\n")} className={b.failed ? "text-amber-700" : ""}>{b.failed}</Cell><Cell>{b.failed > 0 && <div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => { setCsv(b.payload); setImportFile(b.fileName + " (corrected)"); setImportError(""); toast("Failed rows loaded for correction."); }}>Edit failed</Button><Button variant="outline" size="sm" disabled={integrationUnavailable} onClick={() => processImport(b.payload, b.fileName + " (retry)")}><RefreshCw />Retry failed</Button></div>}</Cell></Row>)}</TableWrap>
      {!data.imports.length && <Empty>Import batches will appear here after the first run.</Empty>}
    </>}
    {section === "history" && <>
      <section aria-label="Activity history overview" className={`${panelClass} grid gap-4 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-center`}><div className="min-w-0"><p className="text-xs font-medium text-muted-foreground">Workspace audit trail</p><p className="mt-1 text-2xl font-semibold tabular-nums">{formatNumber(data.history.length)} <span className="text-sm font-normal text-muted-foreground">events recorded</span></p><p className="mt-1 max-w-2xl text-xs text-muted-foreground">Review actions in newest-first order. Export a backup before restoring or resetting local data.</p></div><div className="flex flex-wrap gap-2 sm:flex-nowrap sm:justify-end"><Button className="shrink-0" variant="outline" onClick={() => downloadBackup(data)}><ArrowDownToLine />Export backup</Button><label className="inline-flex h-9 shrink-0 cursor-pointer items-center gap-2 rounded-md border px-3 text-sm hover:bg-muted"><FileUp className="size-4" />Restore backup<input type="file" accept="application/json,.json" className="sr-only" onChange={(e) => { const file = e.target.files?.[0]; if (file) void file.text().then((text) => { try { const parsed: unknown = JSON.parse(text); if (!isForgeData(parsed)) throw new Error(); update(() => parsed, "Workspace backup restored", file.name); toast.success("Backup restored"); } catch { toast.error("That file is not a valid ForgeFlow backup."); } }); }} /></label><Button className="shrink-0" variant="destructive" onClick={() => setConfirmReset(true)}><RotateCcw />Reset demo data</Button></div></section>
      {confirmReset && <div role="alertdialog" aria-modal="true" className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-destructive/30 bg-destructive/5 p-4"><p className="text-sm">Reset all local records to the original demo dataset? This cannot be undone.</p><div className="flex gap-2"><Button variant="outline" onClick={() => setConfirmReset(false)}>Cancel</Button><Button variant="destructive" onClick={() => { reset(); setConfirmReset(false); toast.success("Demo data restored"); }}>Confirm reset</Button></div></div>}
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><SearchBox query={query} setQuery={(value) => { setQuery(value); setHistoryPage(1); }} placeholder="Search action or details…" /><p className="text-xs text-muted-foreground">{matchingHistory.length ? `${formatNumber(historyStart + 1)}–${formatNumber(Math.min(historyStart + historyPageSize, matchingHistory.length))} of ${formatNumber(matchingHistory.length)} events` : "No matching events"}</p></div>
      {pagedHistory.length ? <><TableWrap serialOffset={historyStart} headers={["Time", "Action", "Details"]}>{pagedHistory.map((a) => { const expanded = expandedHistoryDetails.includes(a.id); const canExpand = a.detail.length > 150; return <Row key={a.id}><Cell className="text-xs text-muted-foreground">{new Intl.DateTimeFormat("en-IN", { dateStyle: "medium", timeStyle: "short" }).format(new Date(a.createdAt))}</Cell><Cell className="font-medium">{a.action}</Cell><Cell className="w-1/2 max-w-[34rem] whitespace-normal text-muted-foreground"><div className="max-w-[34rem] break-words text-xs leading-5"><p className={expanded ? "" : "line-clamp-2"}>{a.detail}</p>{canExpand && <button type="button" aria-expanded={expanded} onClick={() => setExpandedHistoryDetails((ids) => expanded ? ids.filter((id) => id !== a.id) : [...ids, a.id])} className="mt-1 text-[11px] font-medium text-primary hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{expanded ? "Show less" : "Show full details"}</button>}</div></Cell></Row>; })}</TableWrap><nav aria-label="Activity history pages" className="flex flex-wrap items-center justify-between gap-3"><p className="text-xs text-muted-foreground">Page {currentHistoryPage} of {historyPageCount} · 20 events per page</p><div className="flex gap-2"><Button variant="outline" size="sm" disabled={currentHistoryPage <= 1} onClick={() => setHistoryPage((page) => Math.max(1, page - 1))}>Previous</Button><Button variant="outline" size="sm" disabled={currentHistoryPage >= historyPageCount} onClick={() => setHistoryPage((page) => Math.min(historyPageCount, page + 1))}>Next</Button></div></nav></> : <div className={`${panelClass} border-dashed text-center`}><p className="font-medium">{data.history.length ? "No activity matches this search" : "No activity recorded yet"}</p><p className="mt-1 text-sm text-muted-foreground">{data.history.length ? "Try a different action or detail." : "Workspace changes will appear here with their date, action, and details."}</p></div>}
    </>}
  </div>;
}

function latestReconciliations(items: ForgeData["reconciliations"]) {
  const latest = new Map<string, ForgeData["reconciliations"][number]>();
  for (const item of [...items].sort((a, b) => b.createdAt.localeCompare(a.createdAt))) if (!latest.has(item.orderId)) latest.set(item.orderId, item);
  return [...latest.values()];
}

function ReconciliationSummary({ label, value, detail }: { label: string; value: number; detail: string }) {
  return <div className={`${panelClass} p-4`}><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 text-2xl font-semibold tabular-nums">{formatNumber(value)}</p><p className="mt-1 text-[11px] text-muted-foreground">{detail}</p></div>;
}

function ReconciliationForm({ open, onOpenChange, orders, data, onSubmit }: { open: boolean; onOpenChange: (open: boolean) => void; orders: ProductionOrder[]; data: ForgeData; onSubmit: (values: FormData) => boolean }) {
  const [orderId, setOrderId] = useState(orders[0]?.id ?? "");
  const [reportedText, setReportedText] = useState("");
  const order = orders.find((item) => item.id === orderId);
  const flow = order ? calculateOrderFlow(data, order) : null;
  const latest = order ? latestReconciliations(data.reconciliations.filter((item) => item.orderId === order.id))[0] : undefined;
  const reportQuantity = Number(reportedText);
  const reportValid = reportedText.trim() !== "" && Number.isSafeInteger(reportQuantity) && reportQuantity >= 0;
  const resetDraft = () => { setOrderId(orders[0]?.id ?? ""); setReportedText(""); };
  const changeOpen = (next: boolean) => { onOpenChange(next); if (!next) resetDraft(); };
  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (onSubmit(new FormData(event.currentTarget))) { resetDraft(); onOpenChange(false); } };
  const delta = (label: string, value: number) => <span className="rounded-md bg-background px-2.5 py-1.5 text-[11px] text-muted-foreground">{label}: <b className={value === 0 ? "text-emerald-700 dark:text-emerald-300" : "text-amber-700 dark:text-amber-300"}>{value > 0 ? "+" : ""}{formatNumber(value)}</b></span>;

  return <Sheet open={open} onOpenChange={changeOpen}>
    <SheetContent aria-describedby="new-reconciliation-description" className="flex h-dvh w-full max-w-none flex-col gap-0 overflow-hidden p-0 sm:max-w-xl">
      <div className="border-b bg-gradient-to-br from-primary/[0.08] via-background to-background px-5 py-5 pr-14 sm:px-7 sm:py-6"><div className="flex items-start gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><Scale aria-hidden="true" className="size-5" /></span><div className="min-w-0"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Vendor reconciliation</p><SheetTitle className="mt-1 text-xl font-semibold tracking-tight">New vendor report</SheetTitle><SheetDescription id="new-reconciliation-description" className="mt-1 text-xs leading-5">Record what the vendor reports and compare it with your dispatch and warehouse counts.</SheetDescription></div></div></div>
      <form onSubmit={submit} className="flex min-h-0 flex-1 flex-col">
        <div className="min-h-0 flex-1 space-y-5 overflow-y-auto px-5 py-5 sm:px-7 sm:py-6">
          {orders.length ? <>
            <section aria-labelledby="reconciliation-report-heading" className="space-y-3.5"><div className="flex items-start justify-between gap-3"><div><h3 id="reconciliation-report-heading" className="text-sm font-semibold">Vendor report</h3><p className="mt-0.5 text-[11px] text-muted-foreground">Enter the total quantity the vendor says has been returned.</p></div><span className="rounded-full border bg-muted/40 px-2 py-1 text-[9px] font-medium text-muted-foreground">Required</span></div>
              <label htmlFor="reconciliation-order" className={fieldClass}>Production order<select id="reconciliation-order" name="orderId" required value={orderId} onChange={(event) => setOrderId(event.target.value)} className={selectClass}><option value="" disabled>Select an order</option>{orders.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.product}</option>)}</select></label>
              <label htmlFor="reconciliation-reported" className={fieldClass}>Vendor-reported returned quantity<Input id="reconciliation-reported" name="reported" type="number" min={0} step={1} required value={reportedText} onChange={(event) => setReportedText(event.target.value)} placeholder="Enter returned units reported by vendor" /><span className="text-[10px] font-normal">Enter 0 if the vendor has not returned any units yet.</span></label>
            </section>
            {order && flow && <section aria-label="Selected order quantity context" className="rounded-xl border bg-muted/25 p-4" aria-live="polite"><div className="flex flex-wrap items-start justify-between gap-2"><div><h3 className="text-xs font-semibold">Quantity context</h3><p className="mt-1 text-[10px] text-muted-foreground">Compare the vendor’s statement with quantities recorded in this order.</p></div><Link className="text-[11px] font-medium text-primary hover:underline" href={`/orders/${order.id}`}>View order <ArrowRight className="inline size-3" /></Link></div>
              <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">{[["Order quantity", order.quantity], ["Dispatched", flow.dispatched], ["Earlier report", latest ? latest.reported : null], ["Physically received", flow.received], ["Quality accepted", flow.accepted], ["Invoiced", flow.invoiced]].map(([label, value]) => <div key={String(label)} className="rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">{label}</p><p className="mt-0.5 text-sm font-semibold tabular-nums">{value === null ? "None" : formatNumber(Number(value))}</p></div>)}</div>
              {reportValid && <div className="mt-3 flex flex-wrap gap-2">{delta("Reported − dispatched", reportQuantity - flow.dispatched)}{delta("Reported − received", reportQuantity - flow.received)}</div>}
            </section>}
            <div className="flex items-start gap-2 rounded-lg border border-blue-200/70 bg-blue-50/60 p-3 text-[11px] leading-4 text-blue-900 dark:border-blue-900 dark:bg-blue-950/30 dark:text-blue-200"><CircleAlert aria-hidden="true" className="mt-0.5 size-4 shrink-0" /><p>Vendor-reported quantity is a statement, not a stock adjustment. Record the physical count separately in Warehouse receipts. If the report exceeds dispatch or receipt, save it and investigate the difference.</p></div>
          </> : <div className="rounded-xl border border-dashed p-6 text-center"><p className="text-sm font-medium">No production orders to reconcile</p><p className="mt-1 text-xs text-muted-foreground">Create an order first, then record a vendor quantity update.</p><Button className="mt-4" type="button" variant="outline" asChild><Link href="/orders">Open production orders <ArrowRight className="size-3.5" /></Link></Button></div>}
        </div>
        <div className="flex flex-col-reverse gap-2 border-t bg-background px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-7"><p className="text-[10px] text-muted-foreground">This creates a dated report snapshot for the selected order.</p><div className="flex gap-2"><Button type="button" variant="outline" onClick={() => changeOpen(false)}>Cancel</Button><Button type="submit" disabled={!order || !reportValid}><Plus aria-hidden="true" />Save vendor report</Button></div></div>
      </form>
    </SheetContent>
  </Sheet>;
}

function ReconciliationList({ data, query, status, resolvingId, resolutionDraft, onResolveOpen, onResolutionChange, onCancelResolve, onResolve }: { data: ForgeData; query: string; status: "All" | "Open" | "Resolved"; resolvingId: string | null; resolutionDraft: string; onResolveOpen: (id: string) => void; onResolutionChange: (value: string) => void; onCancelResolve: () => void; onResolve: (id: string) => void }) {
  const reports = [...data.reconciliations].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const latestIds = new Set(latestReconciliations(reports).map((item) => item.id));
  const filtered = reports.filter((item) => {
    if (status !== "All" && item.status !== status) return false;
    const order = data.orders.find((candidate) => candidate.id === item.orderId);
    const vendor = data.vendors.find((candidate) => candidate.id === item.vendorId);
    const haystack = [order?.code, order?.product, vendor?.name, vendor?.code, item.externalId].filter(Boolean).join(" ").toLocaleLowerCase();
    return haystack.includes(query.trim().toLocaleLowerCase());
  });
  if (!reports.length) return <div className={`${panelClass} text-center`}><p className="font-medium">No vendor reports yet</p><p className="mt-1 text-sm text-muted-foreground">Record a report here or import a vendor update to compare it with warehouse and quality records.</p></div>;
  if (!filtered.length) return <div className={`${panelClass} text-center text-sm text-muted-foreground`}>No {status === "All" ? "reports" : status.toLocaleLowerCase() + " reports"} match this search.</div>;
  const metric = (label: string, value: number | undefined, emphasis = false) => <div className="min-w-0 rounded-lg border bg-background px-3 py-2"><p className="text-[10px] text-muted-foreground">{label}</p><p className={`mt-0.5 truncate text-sm font-semibold tabular-nums ${emphasis ? "text-amber-700 dark:text-amber-300" : ""}`}>{value === undefined ? "Not captured" : formatNumber(value)}</p></div>;
  const variance = (label: string, value: number | undefined) => <span className="inline-flex items-center gap-1 rounded-md bg-muted/50 px-2 py-1 text-[10px] text-muted-foreground">{label}: <b className={value === undefined || value === 0 ? "text-foreground" : "text-amber-700 dark:text-amber-300"}>{value === undefined ? "Not captured" : `${value > 0 ? "+" : ""}${formatNumber(value)}`}</b></span>;
  return <div className="space-y-3">{filtered.map((item, index) => {
    const order = data.orders.find((candidate) => candidate.id === item.orderId);
    const vendor = data.vendors.find((candidate) => candidate.id === item.vendorId);
    const isLatest = latestIds.has(item.id);
    const progress = calculateReconciliationProgress(data, item);
    const qualityLossAtReport = item.received - item.accepted;
    return <article key={item.id} className={`${panelClass} space-y-3`}>
      <div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="rounded-md bg-muted px-2 py-1 text-[10px] font-medium tabular-nums text-muted-foreground">S.No. {index + 1}</span><Link href={order ? `/orders/${order.id}` : "/orders"} className="font-semibold text-primary hover:underline">{order?.code ?? "Deleted order"}</Link><StatusBadge status={item.status} /><span className={`rounded-full px-2 py-0.5 text-[10px] font-medium ${isLatest ? "bg-primary/10 text-primary" : "bg-muted text-muted-foreground"}`}>{isLatest ? "Latest update" : "Earlier update"}</span></div><p className="mt-1 truncate text-xs text-muted-foreground">{vendor?.name ?? "Unknown vendor"}{order?.product ? ` · ${order.product}` : ""}</p><p className="mt-1 text-[11px] text-muted-foreground">{item.externalId ? `Vendor reference ${item.externalId} · ` : "Manual report · "}{new Date(item.createdAt).toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" })}</p></div>
        {item.status === "Open" && resolvingId !== item.id && <Button size="sm" variant="outline" onClick={() => onResolveOpen(item.id)}><Check className="size-4" />Resolve with note</Button>}
      </div>
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 xl:grid-cols-7">{metric("Vendor reported", item.reported, true)}{metric("Dispatched at report", item.dispatched)}{metric("Received at report", item.received)}{metric("Received now", progress?.received ?? item.received)}{metric("Accepted now", progress?.accepted ?? item.accepted)}{metric("Rejected / held now", progress?.rejected ?? qualityLossAtReport)}{metric("Invoiced now", progress?.invoiced ?? item.invoiced)}</div>
      <p className="rounded-md border bg-muted/20 px-3 py-2 text-[10px] leading-4 text-muted-foreground">Report figures are preserved as a dated snapshot; live warehouse and quality totals update as receipts are entered.</p>
      <div className="flex flex-wrap gap-2">{variance("Report − dispatched at report", item.dispatched === undefined ? undefined : item.reported - item.dispatched)}{variance("Report − received now", progress ? item.reported - progress.received : item.reported - item.received)}{variance("Invoice − received now", progress ? progress.invoiced - progress.received : item.invoiced === undefined ? undefined : item.invoiced - item.received)}{item.dispatched !== undefined && item.reported > item.dispatched && <span className="rounded-md bg-rose-50 px-2 py-1 text-[10px] font-semibold text-rose-800 dark:bg-rose-950/40 dark:text-rose-200">Vendor reported {formatNumber(item.reported - item.dispatched)} more than was dispatched at report time</span>}{item.status === "Open" && isLatest && progress && progress.reportedOutstanding > 0 && <span className="rounded-md bg-amber-50 px-2 py-1 text-[10px] font-medium text-amber-800 dark:bg-amber-950/40 dark:text-amber-200">{formatNumber(progress.reportedOutstanding)} reported units not yet physically received</span>}{item.status === "Open" && isLatest && progress && progress.receivedAboveReport > 0 && <span className="rounded-md bg-amber-50 px-2 py-1 text-[10px] font-medium text-amber-800 dark:bg-amber-950/40 dark:text-amber-200">Warehouse has received {formatNumber(progress.receivedAboveReport)} more units than the vendor reported</span>}{item.status === "Open" && isLatest && progress && progress.reportedOutstanding === 0 && progress.receivedAboveReport === 0 && <span className="rounded-md bg-emerald-50 px-2 py-1 text-[10px] font-medium text-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-200">All reported units are physically received · add a resolution note to close this report</span>}{!isLatest && item.status === "Open" && <span className="rounded-md bg-muted px-2 py-1 text-[10px] text-muted-foreground">Earlier report · use the latest update above for the current outstanding quantity</span>}</div>
      {item.status === "Resolved" && <div className="rounded-lg border border-emerald-200 bg-emerald-50/50 p-3 text-xs dark:border-emerald-900 dark:bg-emerald-950/20"><p className="font-medium">Resolution recorded{item.resolvedAt ? ` · ${new Date(item.resolvedAt).toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" })}` : ""}</p><p className="mt-1 text-muted-foreground">{item.resolutionNote || "No resolution note available."}</p></div>}
      {resolvingId === item.id && <form className="rounded-xl border bg-muted/20 p-3" onSubmit={(event) => { event.preventDefault(); onResolve(item.id); }}><label className="grid gap-1.5 text-xs font-medium text-muted-foreground">Investigation outcome or agreed next action<textarea autoFocus required maxLength={500} value={resolutionDraft} onChange={(event) => onResolutionChange(event.target.value)} placeholder="For example: Vendor confirmed 700 units remain in transit; warehouse to verify on arrival by 18 Nov." className="min-h-20 rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring" /></label><p className="mt-1 text-right text-[10px] text-muted-foreground">{resolutionDraft.length}/500</p><div className="mt-2 flex flex-wrap justify-end gap-2"><Button type="button" size="sm" variant="ghost" onClick={onCancelResolve}>Cancel</Button><Button size="sm" disabled={!resolutionDraft.trim()}>Save resolution</Button></div></form>}
    </article>;
  })}</div>;
}

function QualityInspectionForm({ open, onOpenChange, receipts, data, onSubmit }: { open: boolean; onOpenChange: (open: boolean) => void; receipts: ForgeData["receipts"]; data: ForgeData; onSubmit: (values: FormData) => boolean }) {
  const [receiptId, setReceiptId] = useState(receipts[0]?.id ?? "");
  const [acceptedText, setAcceptedText] = useState("");
  const [rejectedText, setRejectedText] = useState("");
  const [notes, setNotes] = useState("");
  const receipt = receipts.find((item) => item.id === receiptId);
  const order = receipt ? data.orders.find((item) => item.id === receipt.orderId) : undefined;
  const vendor = receipt ? data.vendors.find((item) => item.id === receipt.vendorId) : undefined;
  const accepted = Number(acceptedText);
  const rejected = Number(rejectedText);
  const splitEntered = acceptedText.trim() !== "" && rejectedText.trim() !== "";
  const validNumbers = splitEntered && Number.isSafeInteger(accepted) && Number.isSafeInteger(rejected) && accepted >= 0 && rejected >= 0;
  const allocated = validNumbers ? accepted + rejected : (Number.isSafeInteger(accepted) && accepted >= 0 ? accepted : 0) + (Number.isSafeInteger(rejected) && rejected >= 0 ? rejected : 0);
  const remaining = receipt ? receipt.quantity - allocated : 0;
  const splitValid = !!receipt && validNumbers && allocated === receipt.quantity;
  const noteRequired = rejected > 0;
  const canSubmit = splitValid && (!noteRequired || !!notes.trim());
  const progress = receipt?.quantity ? Math.max(0, Math.min(100, allocated / receipt.quantity * 100)) : 0;
  const resetDraft = () => { setReceiptId(receipts[0]?.id ?? ""); setAcceptedText(""); setRejectedText(""); setNotes(""); };
  const handleOpenChange = (next: boolean) => { onOpenChange(next); if (!next) resetDraft(); };
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (onSubmit(new FormData(event.currentTarget))) { resetDraft(); onOpenChange(false); } };

  return <Sheet open={open} onOpenChange={handleOpenChange}>
    <SheetContent aria-describedby="new-inspection-description" className="flex h-dvh w-full max-w-none flex-col gap-0 overflow-hidden p-0 sm:max-w-2xl">
      <div className="border-b bg-gradient-to-br from-primary/[0.08] via-background to-background px-5 py-5 pr-14 sm:px-7 sm:py-6"><div className="flex items-start gap-3"><span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><ShieldAlert aria-hidden="true" className="size-5" /></span><div className="min-w-0"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Quality control</p><SheetTitle className="mt-1 text-xl font-semibold tracking-tight">Record inspection</SheetTitle><SheetDescription id="new-inspection-description" className="mt-1 text-xs leading-5">Classify every unit on one warehouse receipt as accepted or rejected / held.</SheetDescription></div></div></div>
      <form onSubmit={handleSubmit} className="flex min-h-0 flex-1 flex-col">
        <div className="min-h-0 flex-1 space-y-5 overflow-y-auto px-5 py-5 sm:px-7 sm:py-6">
          {receipts.length ? <>
            <section aria-labelledby="inspection-receipt-heading" className="space-y-3"><div><h3 id="inspection-receipt-heading" className="text-sm font-semibold">Choose a goods receipt</h3><p className="mt-0.5 text-[11px] text-muted-foreground">Each receipt can be inspected once. The received quantity is the control total.</p></div>
              <label htmlFor="inspection-receipt" className={fieldClass}>Uninspected receipt<select id="inspection-receipt" className={selectClass} name="receiptId" required value={receiptId} onChange={(event) => { setReceiptId(event.target.value); setAcceptedText(""); setRejectedText(""); setNotes(""); }}><option value="" disabled>Select a receipt to inspect</option>{receipts.map((item) => <option key={item.id} value={item.id}>{item.reference} · {data.orders.find((x) => x.id === item.orderId)?.code ?? "Order"} · {formatNumber(item.quantity)} units</option>)}</select></label>
              {receipt ? <div className="rounded-xl border bg-muted/25 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-wide text-muted-foreground">Selected goods receipt</p><p className="mt-1 text-sm font-semibold">{receipt.reference}</p><p className="mt-1 text-xs text-muted-foreground">{order?.code ?? "Unknown order"} · {order?.product ?? "Unknown product"}</p><p className="mt-1 text-[11px] text-muted-foreground">{vendor?.name ?? "Unknown vendor"} · received {formatDate(receipt.receivedAt)}</p></div><div className="min-w-36 rounded-lg border bg-background px-3 py-2 text-right"><p className="text-[9px] uppercase tracking-wide text-muted-foreground">Quantity to account for</p><p className="text-xl font-semibold tabular-nums">{formatNumber(receipt.quantity)} <span className="text-xs font-normal text-muted-foreground">units</span></p></div></div><p className="mt-3 border-t pt-3 text-[11px] leading-4 text-muted-foreground">Inspect the delivered pieces against your quality criteria. Only accepted units become usable stock; rejected / held units remain unavailable.</p></div> : <p className="rounded-lg border border-dashed p-4 text-sm text-muted-foreground">Choose a receipt to see its exact quantity and order details.</p>}
            </section>
            <section aria-labelledby="inspection-result-heading" className="space-y-3 border-t pt-5"><div className="flex flex-wrap items-end justify-between gap-2"><div><h3 id="inspection-result-heading" className="text-sm font-semibold">Inspection result</h3><p className="mt-0.5 text-[11px] text-muted-foreground">Enter whole unit counts. Accepted plus rejected must match the receipt.</p></div>{receipt && <Button type="button" size="sm" variant="outline" onClick={() => { setAcceptedText(String(receipt.quantity)); setRejectedText("0"); setNotes(""); }}>Accept all {formatNumber(receipt.quantity)}</Button>}</div>
              <div className="grid gap-3 sm:grid-cols-2"><label htmlFor="inspection-accepted" className={fieldClass}>Accepted units<Input id="inspection-accepted" name="accepted" type="number" min={0} max={receipt?.quantity} step={1} value={acceptedText} onChange={(event) => setAcceptedText(event.target.value)} placeholder="Enter accepted count" required disabled={!receipt} className="h-10 text-base font-semibold tabular-nums" /><span className="text-[10px] font-normal">Meets criteria and can enter available stock.</span></label><label htmlFor="inspection-rejected" className={fieldClass}>Rejected / held units<Input id="inspection-rejected" name="rejected" type="number" min={0} max={receipt?.quantity} step={1} value={rejectedText} onChange={(event) => setRejectedText(event.target.value)} placeholder="Enter rejected count" required disabled={!receipt} className="h-10 text-base font-semibold tabular-nums" /><span className="text-[10px] font-normal">Fails criteria; excluded from available stock.</span></label></div>
              <div className="rounded-xl border bg-background p-3.5" aria-live="polite"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="text-xs font-semibold">Quantity reconciliation</p><p className="mt-0.5 text-[11px] text-muted-foreground">Accepted + rejected = received quantity.</p></div>{receipt && <p className={`text-sm font-semibold tabular-nums ${splitValid ? "text-emerald-700 dark:text-emerald-300" : remaining < 0 ? "text-destructive" : "text-amber-700 dark:text-amber-300"}`}>{splitValid ? `All ${formatNumber(receipt.quantity)} units accounted for` : remaining >= 0 ? `${formatNumber(remaining)} units need a result` : `${formatNumber(Math.abs(remaining))} units over receipt quantity`}</p>}</div><div className="mt-3 h-2 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full transition-[width] ${splitValid ? "bg-emerald-500" : remaining < 0 ? "bg-destructive" : "bg-amber-500"}`} style={{ width: `${progress}%` }} /></div>{receipt && <div className="mt-2 flex justify-between gap-2 text-[10px] text-muted-foreground"><span>{formatNumber(validNumbers ? accepted : Math.max(0, Number.isSafeInteger(accepted) ? accepted : 0))} accepted · {formatNumber(validNumbers ? rejected : Math.max(0, Number.isSafeInteger(rejected) ? rejected : 0))} rejected</span><span>{formatNumber(receipt.quantity)} received</span></div>}{receipt && !splitValid && splitEntered && (!Number.isSafeInteger(accepted) || !Number.isSafeInteger(rejected)) && <p className="mt-2 text-xs text-destructive">Enter whole unit counts; fractions are not allowed.</p>}</div>
              <label htmlFor="inspection-notes" className={fieldClass}>Inspection notes {noteRequired ? <span className="text-destructive">· required for rejected units</span> : <span className="font-normal">· optional</span>}<textarea id="inspection-notes" name="notes" maxLength={500} required={noteRequired} value={notes} onChange={(event) => setNotes(event.target.value)} placeholder={noteRequired ? "Describe the defect and current disposition, e.g. surface cracks · hold for vendor review" : "Record sample checks, measurement results, or other findings"} className="min-h-20 rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring" /><span className="text-right text-[10px] font-normal">{notes.length}/500</span></label>
              {rejected > 0 && <p className="rounded-lg border border-amber-200 bg-amber-50/70 p-3 text-[11px] leading-4 text-amber-900 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-200">Rejected units stay out of available stock. Record what failed and whether the parts are held, returned, or awaiting vendor disposition.</p>}
            </section>
          </> : <div className="rounded-xl border border-dashed p-6 text-center"><span className="mx-auto flex size-10 items-center justify-center rounded-xl bg-muted text-muted-foreground"><ShieldAlert aria-hidden="true" className="size-5" /></span><p className="mt-3 text-sm font-semibold">No uninspected receipts</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Record a warehouse receipt first. Each receipt can be inspected once, and every received unit needs an outcome.</p><Button className="mt-4" type="button" variant="outline" asChild><Link href="/warehouse/receipts">Go to warehouse receipts <ArrowRight className="size-3.5" /></Link></Button></div>}
        </div>
        <div className="flex flex-col-reverse gap-2 border-t bg-background px-5 py-4 sm:flex-row sm:items-center sm:justify-between sm:px-7"><p className="text-[10px] text-muted-foreground">One inspection per receipt · rejected quantity requires a note.</p><div className="flex gap-2"><Button type="button" variant="outline" onClick={() => handleOpenChange(false)}>Cancel</Button><Button type="submit" disabled={!receipts.length || !canSubmit}><Check aria-hidden="true" />Save inspection</Button></div></div>
      </form>
    </SheetContent>
  </Sheet>;
}

function downloadBackup(data: ForgeData) { const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `forgeflow-backup-${new Date().toISOString().slice(0, 10)}.json`; a.click(); URL.revokeObjectURL(url); }
function SearchBox({ query, setQuery, placeholder }: { query: string; setQuery: (x: string) => void; placeholder: string }) { return <div className="relative max-w-md"><Search aria-hidden="true" className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={placeholder} className="pl-9" /></div>; }

function OrderRow({ serialNumber, order: o, vendor, received, update, hasLinkedData, today }: { serialNumber: number; order: ProductionOrder; vendor: string; received: number; update: (fn: (d: ForgeData) => ForgeData, a?: string, detail?: string) => void; hasLinkedData: boolean; today: string | null }) {
  return <Row><Cell className="w-14 text-xs tabular-nums text-muted-foreground">{serialNumber}</Cell><Cell><Link href={`/orders/${o.id}`} className="font-medium text-primary hover:underline">{o.code}</Link><div className="text-xs text-muted-foreground">Created {formatDate(o.createdAt)}</div></Cell><Cell>{o.product}</Cell><Cell>{vendor}</Cell><Cell>{formatNumber(o.quantity)}</Cell><Cell className={today && o.dueDate < today && !["Completed", "Shipped"].includes(o.status) ? "text-destructive" : ""}>{formatDate(o.dueDate)}</Cell><Cell>{formatNumber(received)} / {formatNumber(o.quantity)}</Cell><Cell><select aria-label={`Update ${o.code} status`} className="rounded-md border bg-background px-2 py-1 text-xs" value={o.status} onChange={(e) => update((d) => ({ ...d, orders: d.orders.map((x) => x.id === o.id ? { ...x, status: e.target.value as OrderStatus } : x) }), "Order status changed", `${o.code} set to ${e.target.value}`)}>{statuses.map((x) => <option key={x} disabled={x === "Shipped"}>{x}</option>)}</select></Cell><Cell><div className="flex items-center gap-2"><Link className="inline-flex items-center gap-1 text-xs text-primary hover:underline" href={`/orders/${o.id}`}>Details <ArrowRight className="size-3" /></Link><Button size="sm" variant="ghost" title={hasLinkedData ? "Remove linked dispatches, receipts, invoices, shipments, and reconciliations before deleting this order" : "Delete order"} disabled={hasLinkedData} onClick={() => { if (window.confirm(`Delete ${o.code}?`)) update((d) => ({ ...d, orders: d.orders.filter((x) => x.id !== o.id) }), "Production order deleted", `${o.code} · ${o.product}`); }}><Trash2 className="size-4" /></Button></div></Cell></Row>;
}

function DashboardToolbar({ updatedAt, range, setRange, onRefresh }: { updatedAt: string | null; range: DashboardRange; setRange: (range: DashboardRange) => void; onRefresh: () => void }) {
  const ranges: DashboardRange[] = ["Today", "7d", "30d", "90d", "QTD"];
  return <div className="flex min-h-14 flex-wrap items-center justify-between gap-3 rounded-xl border bg-card px-4 py-2 shadow-sm">
    <div className="flex items-center gap-2.5"><span aria-hidden="true" className="size-2.5 rounded-full bg-emerald-500 ring-[3px] ring-emerald-500/10" /><h1 className="text-lg font-semibold tracking-tight">Dashboard</h1><span className="hidden text-xs text-muted-foreground sm:inline">Live · Updated {updatedAt ?? "—"}</span></div>
    <div className="flex flex-wrap items-center gap-1.5">
      <span className="text-[11px] font-medium text-muted-foreground">Activity</span><div role="group" aria-label="Activity date range" className="inline-flex rounded-lg border bg-muted/40 p-0.5">{ranges.map((item) => <button key={item} type="button" aria-pressed={range === item} onClick={() => setRange(item)} className={`rounded-md px-2.5 py-1 text-xs transition-colors ${range === item ? "bg-background font-semibold text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"}`}>{item}</button>)}</div>
      <Button size="sm" variant="outline" onClick={onRefresh}><RefreshCw />Refresh</Button>
    </div>
    <span className="text-xs text-muted-foreground sm:hidden">Live · Updated {updatedAt ?? "—"}</span>
  </div>;
}

function isDeliveryAtRisk(order: ProductionOrder, data: ForgeData, today: string | null) {
  if (!today) return false;
  const due = order.shipmentDueDate ?? order.dueDate;
  const days = Math.ceil((new Date(`${due}T00:00:00Z`).getTime() - new Date(`${today}T00:00:00Z`).getTime()) / 86400000);
  return days <= 2 && calculateOrderFlow(data, order).remainingToShip > 0;
}

function Dashboard({ data, totals, vendorName, today, range }: { data: ForgeData; totals: { active: number; due: number; openReconciliation: number; received: number; deliveryShortfall: number; invoiceVariance: number }; vendorName: (x: string) => string; today: string | null; range: DashboardRange }) {
  const active = data.orders.filter((x) => ["Pending", "In Progress", "Blocked"].includes(x.status));
  const startDate = today ? (() => { const date = new Date(`${today}T00:00:00Z`); if (range === "Today") return today; if (range === "QTD") { date.setUTCMonth(Math.floor(date.getUTCMonth() / 3) * 3, 1); } else { date.setUTCDate(date.getUTCDate() - Number.parseInt(range, 10) + 1); } return date.toISOString().slice(0, 10); })() : null;
  const recent = data.history.filter((item) => (!startDate || item.createdAt.slice(0, 10) >= startDate) && (!today || item.createdAt.slice(0, 10) <= today)).slice(0, 5);
  const qualityRejected = data.inspections.reduce((n, x) => n + x.rejected, 0);
  const featuredOrder = [...data.orders].sort((a, b) => {
    const urgency = (order: ProductionOrder) => {
      const flow = calculateOrderFlow(data, order);
      if (order.status === "Blocked" && flow.remainingToShip > 0) return 3;
      if (isDeliveryAtRisk(order, data, today)) return 2;
      return flow.remainingToShip > 0 ? 1 : 0;
    };
    const urgencyDiff = urgency(b) - urgency(a);
    if (urgencyDiff) return urgencyDiff;
    return (a.shipmentDueDate ?? a.dueDate).localeCompare(b.shipmentDueDate ?? b.dueDate);
  })[0];
  const featuredFlow = featuredOrder ? calculateOrderFlow(data, featuredOrder) : null;
  const attention = data.orders.flatMap((order) => {
    const flow = calculateOrderFlow(data, order);
    const risk = isDeliveryAtRisk(order, data, today);
    const overdue = today !== null && flow.deliveryDueDate < today && flow.remainingToShip > 0;
    const issues = [] as Array<{ key: string; title: string; detail: string; value: number; tone: "critical" | "warning" | "neutral"; icon: typeof AlertTriangle; href: string }>;
    if (risk || overdue || (order.status === "Blocked" && flow.remainingToShip > 0)) issues.push({ key: `${order.id}-delivery`, title: overdue ? "Customer delivery is overdue" : order.status === "Blocked" ? "Production is blocked" : "Customer delivery at risk", detail: `${order.code} · ${formatDate(flow.deliveryDueDate)} due`, value: flow.remainingToShip, tone: overdue || order.status === "Blocked" ? "critical" : "warning", icon: AlertTriangle, href: `/orders/${order.id}` });
    if (flow.reportVsReceipt !== 0) issues.push({ key: `${order.id}-receipt`, title: "Vendor / receipt mismatch", detail: `${order.code} · ${formatNumber(flow.reported)} reported, ${formatNumber(flow.received)} received`, value: Math.abs(flow.reportVsReceipt), tone: "warning", icon: Boxes, href: "/reconciliation" });
    if (flow.rejected > 0) issues.push({ key: `${order.id}-quality`, title: "Quality disposition required", detail: `${order.code} · rejected units remain on hold`, value: flow.rejected, tone: "warning", icon: ShieldAlert, href: "/quality" });
    if (flow.invoiced !== flow.received) issues.push({ key: `${order.id}-invoice`, title: "Invoice quantity variance", detail: `${order.code} · compare invoice with receipt`, value: Math.abs(flow.invoiced - flow.received), tone: "neutral", icon: CircleAlert, href: "/reconciliation" });
    return issues;
  }).sort((a, b) => ({ critical: 0, warning: 1, neutral: 2 }[a.tone] - { critical: 0, warning: 1, neutral: 2 }[b.tone]));
  const visibleAttention = attention.slice(0, 6);
  return <>
    <section aria-label="Production metrics" className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><KpiTile label="Active orders" value={totals.active} icon={Factory} definition="Orders that are pending, in progress, or blocked." /><KpiTile label="Units still to ship" value={formatNumber(totals.deliveryShortfall)} icon={AlertTriangle} definition="Customer demand not yet covered by recorded shipments." warn={totals.deliveryShortfall > 0} /><KpiTile label="Units received" value={formatNumber(totals.received)} icon={Boxes} definition="Total warehouse receipts, before quality inspection." /><KpiTile label="Invoice / receipt variance" value={formatNumber(totals.invoiceVariance)} icon={Scale} definition="Sum of each order’s absolute billed-versus-received difference." warn={totals.invoiceVariance !== 0} /></section>
    {featuredOrder && featuredFlow ? <section className="overflow-hidden rounded-2xl border bg-card shadow-sm">
      <div className="flex flex-wrap items-center justify-between gap-4 border-b bg-gradient-to-r from-slate-950 via-slate-900 to-slate-800 px-5 py-5 text-white sm:px-6">
        <div className="flex min-w-0 items-center gap-3"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-white/10"><Factory className="size-5 text-cyan-300" /></div><div className="min-w-0"><p className="text-xs font-semibold uppercase tracking-[0.18em] text-cyan-200">Order execution · featured</p><h2 className="truncate text-base font-semibold">{featuredOrder.customerName ?? "Customer order"} <span className="font-normal text-white/50">/</span> {featuredOrder.customerOrderCode ?? featuredOrder.code}</h2><p className="mt-0.5 truncate text-sm text-white/65">{featuredOrder.code} · {featuredOrder.product} · {vendorName(featuredOrder.vendorId)}</p></div></div>
        <div className="flex items-center gap-3"><div className={`rounded-full border px-3 py-1.5 text-xs font-medium ${featuredFlow.remainingToShip > 0 ? "border-amber-300/30 bg-amber-300/10 text-amber-100" : "border-emerald-300/30 bg-emerald-300/10 text-emerald-100"}`}><span className="mr-1.5 inline-block size-1.5 rounded-full bg-current" />{featuredFlow.remainingToShip === 0 ? "Demand shipped" : isDeliveryAtRisk(featuredOrder, data, today) ? `${formatNumber(featuredFlow.remainingToShip)} units at risk` : `${formatNumber(featuredFlow.remainingToShip)} units still to ship`}</div><Link href={`/orders/${featuredOrder.id}`} aria-label={`Open ${featuredOrder.code} full workflow`} className="flex size-9 items-center justify-center rounded-lg bg-white/10 transition hover:bg-white/20"><ArrowRight className="size-4" /></Link></div>
      </div>
      <div className="grid gap-0 xl:grid-cols-[1.5fr_.8fr]">
        <div className="p-5 sm:p-6"><div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><p className="text-sm font-semibold uppercase tracking-wider text-muted-foreground">Material flow</p><p className="mt-1 text-sm text-muted-foreground">Each checkpoint uses its own recorded quantity</p></div><div className="text-right"><p className="text-sm text-muted-foreground">Customer delivery due</p><p className="text-sm font-semibold">{formatDate(featuredFlow.deliveryDueDate)}</p></div></div><ManufacturingFlowChart order={featuredOrder} flow={featuredFlow} /></div>
        <div className="border-t bg-muted/20 p-5 sm:p-6 xl:border-l xl:border-t-0"><div className="mb-4 flex items-center justify-between"><div><p className="text-sm font-semibold uppercase tracking-wider text-muted-foreground">Quantity reconciliation</p><p className="mt-1 text-sm text-muted-foreground">Compared with customer demand</p></div><Scale className="size-4 text-muted-foreground" /></div><QuantityComparisonChart order={featuredOrder} flow={featuredFlow} /><div className="mt-4 flex items-center justify-between rounded-xl border bg-background px-3.5 py-3"><div><p className="text-sm text-muted-foreground">Accepted stock ready</p><p className="text-sm font-semibold">{formatNumber(featuredFlow.available)} <span className="font-normal text-muted-foreground">/ {formatNumber(featuredOrder.quantity)} units</span></p></div><div className="text-right"><p className="text-sm text-muted-foreground">Rejected / held</p><p className="text-sm font-semibold text-amber-700">{formatNumber(featuredFlow.rejected)} units</p></div></div></div>
      </div>
      <div className="grid gap-3 border-t bg-muted/20 p-4 sm:grid-cols-2 lg:grid-cols-4 sm:px-6"><VarianceChip label="Still at vendor" value={featuredFlow.stillAtVendor} detail="Dispatched − reported" icon={ArrowDownRight} tone="amber" /><VarianceChip label="Reported, not received" value={featuredFlow.inTransit} detail="Vendor report − receipt" icon={Truck} tone="blue" /><VarianceChip label="Invoice vs receipt" value={featuredFlow.invoiced - featuredFlow.received} detail="Billed quantity − received" icon={ArrowUpRight} tone={featuredFlow.invoiced === featuredFlow.received ? "green" : "rose"} /><VarianceChip label="Unshipped demand" value={featuredFlow.remainingToShip} detail="Demand − shipped" icon={PackageCheck} tone="violet" /></div>
    </section> : <DashboardEmpty />}
    <section className="grid items-stretch gap-4 xl:grid-cols-[1.25fr_.75fr]">
      <div className={`${panelClass} flex h-full flex-col overflow-hidden p-0`}><div className="flex flex-wrap items-center justify-between gap-3 border-b px-5 py-4"><div><div className="flex items-center gap-2"><h2 className="font-semibold">Needs attention</h2>{attention.length > 0 && <span className="rounded-full bg-amber-100 px-2 py-0.5 text-xs font-semibold text-amber-800 dark:bg-amber-950 dark:text-amber-200">{attention.length} open</span>}</div><p className="mt-0.5 text-xs text-muted-foreground">Exceptions that may affect delivery, quality, or payment</p></div><Link className="text-xs font-medium text-primary hover:underline" href="/reconciliation">Open reconciliation <ChevronRight className="inline size-3" /></Link></div>{attention.length ? <><div className="grid flex-1 auto-rows-fr gap-2 p-3 sm:grid-cols-2">{visibleAttention.map((item) => { const Icon = item.icon; const palette = item.tone === "critical" ? "border-rose-200 bg-rose-50/70 text-rose-700 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-300" : item.tone === "warning" ? "border-amber-200 bg-amber-50/70 text-amber-800 dark:border-amber-900 dark:bg-amber-950/30 dark:text-amber-300" : "border-border bg-background text-foreground"; return <Link href={item.href} key={item.key} className={`group flex min-w-0 items-center gap-3 rounded-xl border p-3 transition hover:-translate-y-0.5 hover:shadow-sm ${palette}`}><span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-background/80"><Icon className="size-4" /></span><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2"><span className="truncate text-xs font-semibold">{item.title}</span><span className="shrink-0 text-xs font-bold tabular-nums">{formatNumber(item.value)}<span className="ml-1 text-xs font-normal">units</span></span></span><span className="mt-1 block truncate text-xs opacity-75">{item.detail}</span></span><ChevronRight className="size-3 shrink-0 opacity-40 transition group-hover:translate-x-0.5" /></Link>; })}</div>{attention.length > visibleAttention.length && <p className="border-t px-5 py-3 text-xs text-muted-foreground">Showing {visibleAttention.length} of {attention.length} exceptions. Open reconciliation or orders to review the rest.</p>}</> : <div className="flex flex-1 items-center gap-3 p-5"><span className="flex size-9 items-center justify-center rounded-full bg-emerald-100 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300"><Check className="size-4" /></span><div><p className="text-sm font-medium">No open operational exceptions</p><p className="text-xs text-muted-foreground">Delivery, quality, and invoice quantities are aligned.</p></div></div>}</div>
      <ProductionMixChart data={data} />
    </section>
    <section className="grid gap-4 xl:grid-cols-2"><div className={`${panelClass} overflow-hidden p-0`}><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-semibold">Upcoming production</h2><p className="mt-0.5 text-xs text-muted-foreground">Open orders sorted by production due date</p></div><ClipboardList className="size-4 text-muted-foreground" /></div><div className="divide-y">{[...active].sort((a, b) => a.dueDate.localeCompare(b.dueDate)).slice(0, 5).map((order) => { const flow = calculateOrderFlow(data, order); const pct = Math.min(100, order.quantity ? flow.received / order.quantity * 100 : 0); return <Link href={`/orders/${order.id}`} key={order.id} className="group flex items-center gap-3 px-5 py-3.5 transition hover:bg-muted/35"><span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-primary/8 text-primary"><PackageCheck className="size-4" /></span><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-2"><span className="truncate text-sm font-medium">{order.code} <span className="font-normal text-muted-foreground">· {order.product}</span></span><span className="shrink-0 text-xs font-semibold tabular-nums">{formatNumber(flow.received)}<span className="font-normal text-muted-foreground"> / {formatNumber(order.quantity)}</span></span></span><span className="mt-2 flex items-center gap-2"><span className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted"><span className="block h-full rounded-full bg-sky-500" style={{ width: `${pct}%` }} /></span><span className="w-20 shrink-0 truncate text-right text-xs text-muted-foreground">{vendorName(order.vendorId)}</span></span></span><ChevronRight className="size-4 shrink-0 text-muted-foreground transition group-hover:translate-x-0.5" /></Link>; })}{!active.length && <p className="p-6 text-sm text-muted-foreground">No open production orders.</p>}<div className="border-t px-5 py-3"><Link href="/orders" className="text-xs font-medium text-primary hover:underline">View all orders <ArrowRight className="ml-1 inline size-3" /></Link></div></div></div>
      <div className={`${panelClass} overflow-hidden p-0`}><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-semibold">Recent activity</h2><p className="mt-0.5 text-xs text-muted-foreground">{range} · {formatNumber(qualityRejected)} rejected units recorded</p></div><ActivityIcon className="size-4 text-muted-foreground" /></div><div className="divide-y">{recent.map((item, index) => <div key={item.id} className="flex gap-3 px-5 py-3.5"><span className="relative flex w-4 shrink-0 justify-center"><span className={`mt-1.5 size-2 rounded-full ${index === 0 ? "bg-primary ring-4 ring-primary/10" : "bg-muted-foreground/40"}`} />{index < recent.length - 1 && <span className="absolute top-4 h-full w-px bg-border" />}</span><div className="min-w-0"><p className="text-xs font-semibold">{item.action}</p><p className="mt-0.5 line-clamp-2 text-xs leading-4 text-muted-foreground">{item.detail}</p><p className="mt-1 text-xs text-muted-foreground">{formatDate(item.createdAt)}</p></div></div>)}{!recent.length && <p className="p-5 text-sm text-muted-foreground">Activity will appear here as work is recorded.</p>}<Link href="/history" className="block border-t px-5 py-3 text-xs font-medium text-primary hover:bg-muted/30">View activity history <ArrowRight className="ml-1 inline size-3" /></Link></div></div></section>
    <div className="flex flex-wrap gap-2"><Button variant="outline" asChild><Link href="/orders"><Plus />Create production order</Link></Button><Button variant="outline" asChild><Link href="/warehouse/receipts"><PackageCheck />Record receipt</Link></Button><Button variant="outline" asChild><Link href="/imports"><FileUp />Import vendor update</Link></Button></div>
  </>;
}

function ManufacturingFlowChart({ order, flow }: { order: ProductionOrder; flow: ReturnType<typeof calculateOrderFlow> }) {
  const stages = [
    { label: "Customer demand", value: order.quantity, color: "bg-slate-500", note: "Order target" },
    { label: "Sent to vendor", value: flow.dispatched, color: "bg-blue-600", note: `${formatNumber(Math.max(0, order.quantity - flow.dispatched))} not dispatched` },
    { label: "Vendor reported", value: flow.reported, color: "bg-indigo-600", note: flow.reported <= flow.dispatched ? `${formatNumber(flow.dispatched - flow.reported)} not reported` : `${formatNumber(flow.reported - flow.dispatched)} above dispatch` },
    { label: "Warehouse received", value: flow.received, color: "bg-sky-600", note: flow.received <= flow.reported ? `${formatNumber(flow.reported - flow.received)} report not received` : `${formatNumber(flow.received - flow.reported)} above report` },
    { label: "Quality accepted", value: flow.accepted, color: "bg-emerald-600", note: `${formatNumber(flow.rejected)} rejected / held` },
    { label: "Shipped", value: flow.shipped, color: "bg-violet-600", note: `${formatNumber(flow.remainingToShip)} still to ship` },
  ];
  return <div role="img" aria-label={`Manufacturing quantity flow for ${order.code}: demand ${order.quantity}, dispatched ${flow.dispatched}, vendor reported ${flow.reported}, received ${flow.received}, accepted ${flow.accepted}, shipped ${flow.shipped}.`} className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-6">{stages.map((stage, index) => { const pct = order.quantity ? Math.min(100, stage.value / order.quantity * 100) : 0; return <div key={stage.label} className={`relative rounded-xl border bg-background p-3 ${index === 4 && flow.rejected > 0 ? "border-amber-300/70 bg-amber-50/30 dark:border-amber-900" : ""}`}><div className="flex items-center justify-between gap-1"><span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">0{index + 1}</span>{index > 0 && <span className="text-xs text-muted-foreground">{index === 1 ? "dispatch" : index === 2 ? "vendor ASN" : index === 3 ? "GRN" : index === 4 ? "inspection" : "delivery"}</span>}</div><p className="mt-3 text-xs font-medium leading-4 text-muted-foreground">{stage.label}</p><p className="mt-0.5 text-xl font-semibold tracking-tight tabular-nums">{formatNumber(stage.value)}</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${stage.color}`} style={{ width: `${pct}%` }} /></div><p className="mt-2 min-h-7 text-xs leading-4 text-muted-foreground">{stage.note}</p>{index < stages.length - 1 && <span aria-hidden="true" className="absolute -right-2 top-1/2 z-10 hidden size-4 -translate-y-1/2 items-center justify-center rounded-full border bg-background text-muted-foreground 2xl:flex"><ChevronRight className="size-3" /></span>}</div>; })}</div>;
}

function QuantityComparisonChart({ order, flow }: { order: ProductionOrder; flow: ReturnType<typeof calculateOrderFlow> }) {
  const rows = [
    { label: "Customer demand", value: order.quantity, color: "bg-slate-400" },
    { label: "Vendor dispatched", value: flow.dispatched, color: "bg-blue-600" },
    { label: "Vendor reported", value: flow.reported, color: "bg-indigo-600" },
    { label: "Warehouse received", value: flow.received, color: "bg-sky-600" },
    { label: "Quality accepted", value: flow.accepted, color: "bg-emerald-600" },
    { label: "Invoice quantity", value: flow.invoiced, color: "bg-amber-500" },
    { label: "Customer shipped", value: flow.shipped, color: "bg-violet-600" },
  ];
  const max = Math.max(1, order.quantity);
  return <div role="img" aria-label={`Quantity comparison for ${order.code}, with demand of ${order.quantity} as the full bar. ${rows.map((item) => `${item.label}: ${item.value}`).join("; ")}.`} className="space-y-2.5">{rows.map((row) => <div key={row.label} className="grid grid-cols-[minmax(98px,1fr)_2fr_48px] items-center gap-2"><span className="truncate text-xs text-muted-foreground">{row.label}</span><span className="h-2 overflow-hidden rounded-full bg-muted"><span className={`block h-full min-w-0 rounded-full ${row.color} transition-[width] duration-500`} style={{ width: `${row.value ? Math.max(2, Math.min(100, row.value / max * 100)) : 0}%` }} /></span><span className={`text-right text-xs font-semibold tabular-nums ${row.value > order.quantity ? "text-amber-700 dark:text-amber-300" : ""}`}>{formatNumber(row.value)}{row.value > order.quantity && <span className="ml-0.5 text-xs">↗</span>}</span></div>)}</div>;
}

function VarianceChip({ label, value, detail, icon: Icon, tone }: { label: string; value: number; detail: string; icon: typeof ArrowDownRight; tone: "amber" | "blue" | "green" | "rose" | "violet" }) {
  const styles = { amber: "text-amber-700 dark:text-amber-300", blue: "text-sky-700 dark:text-sky-300", green: "text-emerald-700 dark:text-emerald-300", rose: "text-rose-700 dark:text-rose-300", violet: "text-violet-700 dark:text-violet-300" };
  return <div className="flex items-center gap-2.5 rounded-xl border bg-card px-3 py-2.5"><span className={`flex size-8 shrink-0 items-center justify-center rounded-lg bg-muted/70 ${styles[tone]}`}><Icon className="size-4" /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-muted-foreground">{label}</p><p className="truncate text-xs text-muted-foreground/80">{detail}</p></div><strong className={`text-sm tabular-nums ${styles[tone]}`}>{value > 0 ? "+" : ""}{formatNumber(value)}</strong></div>;
}

function ProductionMixChart({ data }: { data: ForgeData }) {
  const colors: Record<OrderStatus, string> = { Pending: "#94a3b8", "In Progress": "#2563eb", Blocked: "#e11d48", Completed: "#059669", Shipped: "#7c3aed" };
  const counts = statuses.map((status) => ({ status, count: data.orders.filter((order) => order.status === status).length }));
  const total = data.orders.length;
  const segments = counts.flatMap(({ status, count }, index) => { if (!count || !total) return []; const start = counts.slice(0, index).reduce((sum, item) => sum + item.count / total * 100, 0); return [`${colors[status]} ${start}% ${start + count / total * 100}%`]; });
  const gradient = segments.length ? `conic-gradient(${segments.join(", ")})` : "conic-gradient(#e2e8f0 0% 100%)";
  return <div className={`${panelClass} overflow-hidden p-0`}><div className="flex items-center justify-between border-b px-5 py-4"><div><h2 className="font-semibold">Production mix</h2><p className="mt-0.5 text-xs text-muted-foreground">Order count by current status</p></div><Link href="/orders" aria-label="View all production orders" className="flex size-8 items-center justify-center rounded-lg border text-muted-foreground hover:bg-muted"><ArrowRight className="size-4" /></Link></div><div className="flex flex-wrap items-center gap-5 p-5"><div role="img" aria-label={`${total} total production orders`} className="relative size-32 shrink-0 rounded-full" style={{ background: gradient }}><div className="absolute inset-3 flex flex-col items-center justify-center rounded-full bg-card"><span className="text-2xl font-semibold tabular-nums">{formatNumber(total)}</span><span className="text-xs text-muted-foreground">orders</span></div></div><div className="min-w-[140px] flex-1 space-y-2">{counts.map(({ status, count }) => <div key={status} className="flex items-center justify-between gap-3 text-xs"><span className="flex min-w-0 items-center gap-2"><span className="size-2 shrink-0 rounded-full" style={{ background: colors[status] }} /><span className="truncate text-muted-foreground">{status}</span></span><span className="font-semibold tabular-nums">{count}<span className="ml-1 font-normal text-muted-foreground">{total ? `${Math.round(count / total * 100)}%` : ""}</span></span></div>)}</div></div>{!total && <p className="px-5 pb-4 text-xs text-muted-foreground">Create an order to see the production mix.</p>}<div className="border-t px-5 py-3"><Link href="/orders" className="text-xs font-medium text-primary hover:underline">Manage production orders <ArrowRight className="ml-1 inline size-3" /></Link></div></div>;
}

function DashboardEmpty() { return <section className={`${panelClass} flex flex-col items-center justify-center gap-3 py-12 text-center`}><span className="flex size-12 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Factory className="size-6" /></span><div><h2 className="font-semibold">Your production overview starts here</h2><p className="mt-1 text-sm text-muted-foreground">Create an order to track vendor progress, receipts, quality, and delivery.</p></div><Button asChild><Link href="/orders"><Plus />Create production order</Link></Button></section>; }

function OrderWorkflow({ order, data, today, onDispatch, onInvoice, onShipment }: { order: ProductionOrder; data: ForgeData; today: string | null; onDispatch: (orderId: string, values: FormData) => boolean; onInvoice: (orderId: string, values: FormData) => boolean; onShipment: (orderId: string, values: FormData) => boolean }) {
  const [showAllDispatches, setShowAllDispatches] = useState(false);
  const flow = calculateOrderFlow(data, order);
  const deliveryDate = new Date(`${flow.deliveryDueDate}T00:00:00`);
  const currentDate = today ? new Date(`${today}T00:00:00`) : null;
  const daysUntilDue = currentDate ? Math.ceil((deliveryDate.getTime() - currentDate.getTime()) / 86400000) : null;
  const submit = (action: (orderId: string, values: FormData) => boolean) => (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (action(order.id, new FormData(event.currentTarget))) event.currentTarget.reset(); };
  const receipts = data.receipts.filter((item) => item.orderId === order.id);
  const orderDispatches = data.dispatches.filter((item) => item.orderId === order.id).sort((a, b) => b.dispatchedAt.localeCompare(a.dispatchedAt));
  const dispatchTotal = orderDispatches.reduce((total, item) => total + item.quantity, 0);
  const visibleDispatches = showAllDispatches ? orderDispatches : orderDispatches.slice(0, 2);
  const uninspected = receipts.filter((receipt) => !data.inspections.some((inspection) => inspection.receiptId === receipt.id));
  const hasVendorReport = data.reconciliations.some((item) => item.orderId === order.id);
  const nextAction = uninspected.length > 0
    ? { key: "quality", title: "Inspect received units", detail: `${uninspected.length} receipt(s) are waiting for accepted/rejected quantities.`, href: "/quality", button: "Open quality inspection" }
    : flow.inTransit > 0
      ? { key: "receipt", title: "Receive the vendor return", detail: `${formatNumber(flow.inTransit)} unit(s) are reported returned but not yet recorded as physically received.`, href: "/warehouse/receipts", button: "Record warehouse receipt" }
      : flow.stillAtVendor > 0
        ? { key: "vendor", title: hasVendorReport ? "Follow up on the vendor balance" : "Record the vendor’s progress update", detail: hasVendorReport ? `${formatNumber(flow.stillAtVendor)} dispatched unit(s) are not yet reported returned. Get an updated cumulative quantity from the vendor.` : `Ask the vendor how many of the ${formatNumber(flow.dispatched)} dispatched units have been returned so far.`, href: "/reconciliation", button: "Record vendor update" }
        : flow.dispatched < order.quantity
          ? { key: "dispatch", title: "Send the remaining components", detail: `The current vendor batch is reconciled. Record dispatch of up to ${formatNumber(order.quantity - flow.dispatched)} remaining units when they are physically handed over.`, href: "#dispatch-panel", button: "Record vendor dispatch" }
          : flow.available > 0
            ? { key: "shipment", title: "Ship accepted units to the customer", detail: `${formatNumber(flow.available)} accepted unit(s) are available. Rejected units remain on hold.`, href: "#shipment-panel", button: "Record customer shipment" }
            : flow.remainingToShip > 0
              ? { key: "vendor", title: "Resolve the remaining supply shortfall", detail: `${formatNumber(flow.remainingToShip)} unit(s) remain to ship. Review the vendor return and supply plan.`, href: "/reconciliation", button: "Review reconciliation" }
              : { key: "complete", title: "Customer order fulfilled", detail: "All ordered units are recorded as shipped.", href: `/orders/${order.id}`, button: "Review completed order" };
  const steps = [
    { key: "order", label: "Order created", detail: order.code, done: true },
    { key: "dispatch", label: "Vendor dispatch", detail: `${formatNumber(flow.dispatched)} / ${formatNumber(order.quantity)} units`, done: flow.dispatched >= order.quantity },
    { key: "vendor", label: "Vendor update", detail: hasVendorReport ? `${formatNumber(flow.reported)} reported` : "Awaiting update", done: hasVendorReport },
    { key: "receipt", label: "Warehouse receipt", detail: `${formatNumber(flow.received)} received`, done: flow.reported > 0 && flow.inTransit === 0 && flow.received > 0 },
    { key: "quality", label: "Quality inspection", detail: `${formatNumber(flow.accepted)} accepted · ${formatNumber(flow.rejected)} held`, done: receipts.length > 0 && uninspected.length === 0 },
    { key: "shipment", label: "Customer shipment", detail: `${formatNumber(flow.shipped)} / ${formatNumber(order.quantity)} units`, done: flow.shipped >= order.quantity },
  ];
  const risk = daysUntilDue !== null && daysUntilDue <= 2 && flow.acceptedShortfall > 0;
  const panelClassFor = (step: string) => `${panelClass} scroll-mt-24 transition-shadow ${nextAction.key === step ? "border-primary/50 shadow-md ring-1 ring-primary/10" : ""}`;
  const formClass = "grid gap-3 rounded-xl border bg-background/70 p-4 sm:grid-cols-[minmax(0,1fr)_auto] sm:items-end";
  return <section className="space-y-5" aria-label="Material flow and customer delivery">
    <div className={`${panelClass} overflow-hidden p-0`}>
      <div className="flex flex-wrap items-start justify-between gap-3 border-b bg-gradient-to-r from-card to-muted/35 px-5 py-4 sm:px-6"><div className="min-w-0"><p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-primary">Production order · {order.code}</p><h2 className="mt-1 truncate text-lg font-semibold">{order.product}</h2><p className="mt-1 text-xs text-muted-foreground">{order.customerOrderCode ? `${order.customerName || "Customer"} · ${order.customerOrderCode}` : "Customer details not assigned"} · Vendor: {vendorNameForOrder(data, order.vendorId)}</p></div><div className="flex shrink-0 items-center gap-2"><StatusBadge status={risk ? "At risk" : order.status} /><div className="rounded-lg border bg-background px-3 py-1.5 text-right"><p className="text-[9px] uppercase tracking-wide text-muted-foreground">Delivery due</p><p className="text-xs font-semibold">{formatDate(flow.deliveryDueDate)}</p></div></div></div>
      <div className="p-5 sm:p-6"><div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl border bg-background p-3"><p className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">Order quantity</p><p className="mt-1 text-xl font-semibold tabular-nums">{formatNumber(order.quantity)} <span className="text-xs font-normal text-muted-foreground">units</span></p></div><div className="rounded-xl border bg-background p-3"><p className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">Accepted stock available</p><p className="mt-1 text-xl font-semibold tabular-nums text-emerald-700 dark:text-emerald-300">{formatNumber(flow.available)} <span className="text-xs font-normal text-muted-foreground">units</span></p></div><div className={`rounded-xl border p-3 ${risk ? "border-amber-300 bg-amber-50/70 dark:border-amber-900 dark:bg-amber-950/20" : "bg-background"}`}><p className="text-[10px] font-medium uppercase tracking-wide text-muted-foreground">Still needed to ship</p><p className={`mt-1 text-xl font-semibold tabular-nums ${risk ? "text-amber-800 dark:text-amber-300" : ""}`}>{formatNumber(flow.remainingToShip)} <span className="text-xs font-normal text-muted-foreground">units</span></p></div></div>
        <div className="mt-5 overflow-x-auto pb-1"><ol aria-label="Production workflow progress" className="grid min-w-[660px] grid-cols-6">{steps.map((step, index) => { const current = nextAction.key === step.key; const Icon = step.done ? CircleCheck : current ? CircleDot : CircleAlert; return <li key={step.key} className="relative pr-2"><div className="flex items-center">{index > 0 && <span className={`absolute right-1/2 top-4 -z-0 h-px w-full ${step.done ? "bg-emerald-500" : "bg-border"}`} />}<span className={`relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full border bg-background ${step.done ? "border-emerald-500 text-emerald-600" : current ? "border-primary text-primary ring-4 ring-primary/10" : "border-border text-muted-foreground"}`}><Icon className="size-4" /></span></div><p className={`mt-2 truncate text-[10px] font-semibold ${current ? "text-primary" : step.done ? "text-foreground" : "text-muted-foreground"}`}>{step.label}</p><p className="truncate text-[9px] text-muted-foreground">{step.detail}</p></li>; })}</ol></div>
      </div>
      <div className={`flex flex-wrap items-center justify-between gap-3 border-t px-5 py-4 sm:px-6 ${risk ? "bg-amber-50/70 dark:bg-amber-950/20" : "bg-primary/[0.035]"}`}><div className="flex min-w-0 items-start gap-3"><span className={`mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-lg ${risk ? "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200" : "bg-primary/10 text-primary"}`}>{nextAction.key === "complete" ? <Check className="size-4" /> : <ArrowRight className="size-4" />}</span><div className="min-w-0"><p className="text-[9px] font-semibold uppercase tracking-[0.15em] text-muted-foreground">Recommended next step</p><p className="mt-0.5 text-sm font-semibold">{nextAction.title}</p><p className="mt-0.5 text-xs text-muted-foreground">{nextAction.detail}{daysUntilDue !== null && daysUntilDue >= 0 && <span> · {daysUntilDue === 0 ? "Due today" : `Due in ${daysUntilDue} days`}</span>}{daysUntilDue !== null && daysUntilDue < 0 && <span className="text-destructive"> · Overdue by {Math.abs(daysUntilDue)} days</span>}</p></div></div><Button size="sm" variant={risk ? "destructive" : "default"} asChild><Link href={nextAction.href}>{nextAction.button}<ArrowRight className="size-3.5" /></Link></Button></div>
    </div>
    <div className="grid gap-3 sm:grid-cols-3"><VarianceChip label="Vendor report vs receipt" value={flow.reportVsReceipt} detail="Reported quantity − physical receipt" icon={Truck} tone={flow.reportVsReceipt ? "amber" : "green"} /><VarianceChip label="Invoice vs receipt" value={flow.invoiced - flow.received} detail="Billed quantity − physical receipt" icon={ArrowUpRight} tone={flow.invoiced === flow.received ? "green" : "rose"} /><VarianceChip label="Invoice vs accepted" value={flow.invoiced - flow.accepted} detail="Billed quantity − quality accepted" icon={Scale} tone={flow.invoiced === flow.accepted ? "green" : "violet"} /></div>
    <div className="grid gap-5 xl:grid-cols-3">
      <section id="dispatch-panel" className={panelClassFor("dispatch")}><div className="mb-3 flex items-start justify-between gap-2"><div><p className="text-[10px] font-semibold uppercase tracking-wide text-blue-700 dark:text-blue-300">Step 1 · subcontracting</p><h3 className="mt-1 font-semibold">Send components to vendor</h3></div><span className="rounded-full bg-blue-50 px-2 py-1 text-[10px] font-medium text-blue-700 dark:bg-blue-950 dark:text-blue-200">{formatNumber(Math.max(0, order.quantity - flow.dispatched))} left</span></div><p className="mb-3 text-xs text-muted-foreground">Record the quantity physically handed over. A dispatch number is assigned automatically.</p><form onSubmit={submit(onDispatch)} className={formClass}><TextField label="Quantity to send" name="quantity" type="number" defaultValue={String(Math.max(0, order.quantity - flow.dispatched))} /><Button disabled={flow.dispatched >= order.quantity}>Record dispatch</Button></form>{orderDispatches.length ? <div className="mt-3 border-t pt-2"><div className="mb-1 flex items-center justify-between gap-2"><p className="text-[10px] text-muted-foreground">{orderDispatches.length} dispatches · {formatNumber(dispatchTotal)} units total</p>{orderDispatches.length > 2 && <button type="button" aria-expanded={showAllDispatches} onClick={() => setShowAllDispatches((value) => !value)} className="inline-flex items-center gap-1 rounded px-1.5 py-1 text-[10px] font-medium text-primary hover:bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring">{showAllDispatches ? "Show recent" : `View all ${orderDispatches.length}`}<ChevronRight aria-hidden="true" className={`size-3 transition-transform ${showAllDispatches ? "rotate-90" : ""}`} /></button>}</div><ul aria-label="Dispatch history" className={`space-y-2 text-xs ${showAllDispatches ? "max-h-44 overflow-y-auto pr-1" : ""}`}>{visibleDispatches.map((item) => <li key={item.id} className="flex justify-between gap-2 border-t pt-2"><span className="font-medium">{item.reference}</span><span className="tabular-nums">{formatNumber(item.quantity)} · {formatDate(item.dispatchedAt)}</span></li>)}</ul></div> : <p className="mt-3 rounded-lg bg-muted/45 p-3 text-[11px] text-muted-foreground">No vendor dispatch recorded yet.</p>}</section>
      <section className={panelClassFor("invoice")}><div className="mb-3"><p className="text-[10px] font-semibold uppercase tracking-wide text-amber-700 dark:text-amber-300">Accounts payable</p><h3 className="mt-1 font-semibold">Record vendor invoice</h3></div><p className="mb-3 text-xs text-muted-foreground">Enter the billed quantity. Differences from received and accepted quantities stay visible for review.</p><form onSubmit={submit(onInvoice)} className={formClass}><TextField label="Units on invoice" name="quantity" type="number" /><Button variant="outline">Record invoice</Button></form><ul className="mt-3 space-y-2 text-xs">{data.invoices.filter((x) => x.orderId === order.id).map((x) => <li key={x.id} className="flex justify-between gap-2 border-t pt-2"><span>{x.reference}</span><span>{formatNumber(x.quantity)} · {formatDate(x.receivedAt)}</span></li>)}</ul>{!data.invoices.some((x) => x.orderId === order.id) && <p className="mt-3 rounded-lg bg-muted/45 p-3 text-[11px] text-muted-foreground">No vendor invoice recorded yet.</p>}</section>
      <section id="shipment-panel" className={panelClassFor("shipment")}><div className="mb-3 flex items-start justify-between gap-2"><div><p className="text-[10px] font-semibold uppercase tracking-wide text-violet-700 dark:text-violet-300">Customer fulfillment</p><h3 className="mt-1 font-semibold">Ship accepted units</h3></div><span className="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-medium text-emerald-700 dark:bg-emerald-950 dark:text-emerald-200">{formatNumber(flow.available)} available</span></div><p className="mb-3 text-xs text-muted-foreground">Only inspected, accepted units can ship.</p><form onSubmit={submit(onShipment)} className={formClass}><TextField label="Quantity to ship" name="quantity" type="number" defaultValue={flow.available ? String(Math.min(flow.available, flow.remainingToShip)) : undefined} /><Button disabled={flow.available === 0 || flow.remainingToShip === 0}>Record shipment</Button></form><ul className="mt-3 space-y-2 text-xs">{data.shipments.filter((x) => x.orderId === order.id).map((x) => <li key={x.id} className="flex justify-between gap-2 border-t pt-2"><span>{x.reference}</span><span>{formatNumber(x.quantity)} · {formatDate(x.shippedAt)}</span></li>)}</ul>{!data.shipments.some((x) => x.orderId === order.id) && <p className="mt-3 rounded-lg bg-muted/45 p-3 text-[11px] text-muted-foreground">No customer shipment recorded yet.</p>}</section>
    </div>
  </section>;
}

function vendorNameForOrder(data: ForgeData, vendorId: string) { return data.vendors.find((vendor) => vendor.id === vendorId)?.name ?? "selected vendor"; }

function OrderDetail({ order, data, vendorName, receipts, inspections, update, receiptFor, accepted }: { order: ProductionOrder; data: ForgeData; vendorName: string; receipts: ForgeData["receipts"]; inspections: ForgeData["inspections"]; update: (fn: (d: ForgeData) => ForgeData, a?: string, detail?: string) => void; receiptFor: number; accepted: number }) {
  const reconciliations = data.reconciliations.filter((x) => x.orderId === order.id);
  return <><div className="flex flex-wrap items-center gap-2"><StatusBadge status={order.status} /><Link href="/orders" className="text-sm text-primary hover:underline">← All orders</Link></div><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Product", order.product], ["Vendor", vendorName], ["Order quantity", formatNumber(order.quantity)], ["Due date", formatDate(order.dueDate)], ["Received", `${formatNumber(receiptFor)} / ${formatNumber(order.quantity)}`], ["Accepted", formatNumber(accepted)], ["Remaining", formatNumber(Math.max(0, order.quantity - receiptFor))], ["Created", formatDate(order.createdAt)]].map(([label, val]) => <div key={label} className={panelClass}><p className="text-xs text-muted-foreground">{label}</p><p className="mt-1 font-semibold">{val}</p></div>)}</section><div className="grid gap-5 xl:grid-cols-2"><section className={panelClass}><h2 className="mb-4 font-semibold">Receipts and inspection</h2>{receipts.length ? <div className="space-y-3">{receipts.map((r) => { const i = inspections.find((x) => x.receiptId === r.id); return <div key={r.id} className="rounded-lg border p-3"><div className="flex justify-between gap-2"><span className="font-medium">{r.reference}</span><span>{formatNumber(r.quantity)} units</span></div><p className="text-xs text-muted-foreground">{formatDate(r.receivedAt)} · {i ? `${formatNumber(i.accepted)} accepted / ${formatNumber(i.rejected)} rejected` : "Awaiting inspection"}</p></div>; })}</div> : <p className="text-sm text-muted-foreground">No receipts recorded for this order.</p>}<div className="mt-4 flex gap-2"><Button variant="outline" asChild><Link href="/warehouse/receipts">Record receipt</Link></Button><Button variant="outline" asChild><Link href="/quality">Quality inspection</Link></Button></div></section><section className={panelClass}><h2 className="mb-4 font-semibold">Progress and reconciliation</h2><label className="grid max-w-xs gap-1.5 text-xs font-medium text-muted-foreground">Update order status<select aria-label="Order status" className={selectClass} value={order.status} onChange={(e) => update((d) => ({ ...d, orders: d.orders.map((x) => x.id === order.id ? { ...x, status: e.target.value as OrderStatus } : x) }), "Order status changed", `${order.code} set to ${e.target.value}`)}>{statuses.map((x) => <option key={x} disabled={x === "Shipped"}>{x}</option>)}</select></label><p className="mt-4 text-sm text-muted-foreground">Accepted output is {formatNumber(accepted)} of {formatNumber(order.quantity)} units.</p><Button className="mt-4" variant="outline" asChild><Link href="/reconciliation">Open reconciliation</Link></Button><ul className="mt-4 space-y-2">{reconciliations.map((r) => { const currentAccepted = data.receipts.filter((x) => x.orderId === order.id).reduce((n, receipt) => n + data.inspections.filter((i) => i.receiptId === receipt.id).reduce((m, i) => m + i.accepted, 0), 0); return <li key={r.id} className="flex justify-between gap-2 border-t pt-2 text-sm"><span>Vendor reported {formatNumber(r.reported)} · accepted {formatNumber(currentAccepted)}</span><StatusBadge status={r.status} /></li>; })}</ul></section></div></>;
}

function VendorDetail({ vendor, data, update }: { vendor: Vendor; data: ForgeData; update: (fn: (d: ForgeData) => ForgeData, a?: string, detail?: string) => void }) { const orders = data.orders.filter((x) => x.vendorId === vendor.id); return <><div className="flex flex-wrap items-center gap-2"><StatusBadge status={vendor.status} /><span className="text-xs text-muted-foreground">{vendor.code}</span><Button variant="outline" size="sm" onClick={() => update((d) => ({ ...d, vendors: d.vendors.map((x) => x.id === vendor.id ? { ...x, status: x.status === "Active" ? "On Hold" : "Active" } : x) }), "Vendor status changed", `${vendor.name} status updated`)}>{vendor.status === "Active" ? "Place on hold" : "Reactivate"}</Button><Link href="/vendors" className="ml-auto text-sm text-primary hover:underline">← All vendors</Link></div><section className="grid gap-3 sm:grid-cols-3"><div className={panelClass}><p className="text-xs text-muted-foreground">Contact</p><p className="mt-1 font-medium">{vendor.contact}</p></div><div className={panelClass}><p className="text-xs text-muted-foreground">Email</p><a className="mt-1 block text-primary hover:underline" href={`mailto:${vendor.email}`}>{vendor.email}</a></div><div className={panelClass}><p className="text-xs text-muted-foreground">Workload</p><p className="mt-1 font-medium">{orders.length} orders · {formatNumber(orders.reduce((n, x) => n + x.quantity, 0))} units</p></div></section><TableWrap headers={["Order", "Product", "Quantity", "Due date", "Status"]}>{orders.map((x) => <Row key={x.id}><Cell><Link href={`/orders/${x.id}`} className="text-primary hover:underline">{x.code}</Link></Cell><Cell>{x.product}</Cell><Cell>{formatNumber(x.quantity)}</Cell><Cell>{formatDate(x.dueDate)}</Cell><Cell><StatusBadge status={x.status} /></Cell></Row>)}</TableWrap>{!orders.length && <Empty>No production orders assigned to this vendor.</Empty>}</>; }
